quests[9194] = { id = 9194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksverfügung - Runenstoffrobe", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer TR-7229:\n\n8 Runenstoffroben.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", sourceObjective = "Bringt 8 Runenstoffroben und die Handwerksverfügung für die Runenstoffroben zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", progress = "Ihr führt einen Auftrag aus, {class}?", completion = "Das war doch völlig unnötig! Nein wirklich, wer hat sich das denn einfallen lassen? Keiner von uns wird ernsthaft beim Sturm auf Naxxramas eine Robe tragen wollen. Was hat Metz sich bloß dabei gedacht?\n\n<Rottenkommandant Stonebruiser seufzt.>\n\nBah, nur wieder eine weitere Ladung unnützes Zeug, das ich an die Front schaffen muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[9195] = { id = 9195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksverfügung - Goblinpioniersprengladung", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer EN-11:\n\n20 Goblinpioniersprengladungen.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", sourceObjective = "Bringt 20 Goblinpioniersprengladungen und die Handwerksverfügung für die Goblinpioniersprengladungen zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[9196] = { id = 9196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksverfügung - Thoriumgranate", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer EN-7:\n\n20 Thoriumgranaten.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", sourceObjective = "Bringt 20 Thoriumgranaten und die Handwerksverfügung für die Thoriumgranaten zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", progress = "Ihr führt einen Auftrag aus, {class}?", completion = "Die Herstellung dieser Dinger muss ganz schön kostspielig gewesen sein. Hab ich Recht, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[9197] = { id = 9197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksverfügung - Gnomenkampfhuhn", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer EN-0:\n\n4 Gnomenkampfhühner.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", sourceObjective = "Bringt 4 Gnomenkampfhühner und die Handwerksverfügung für die Gnomenkampfhühner zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[9198] = { id = 9198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksverfügung - Thoriumröhre", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer EN-558:\n\n14 Thoriumröhren.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", sourceObjective = "Bringt 14 Thoriumröhren und die Handwerksverfügung für die Thoriumröhren zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", progress = "Ihr führt einen Auftrag aus, {class}?", completion = "Thoriumröhren? Wow, danke.\n\n<Rottenkommandant Stonebruiser wirft den Stapel Thoriumröhren auf einen der vielen Schrotthaufen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[9199] = { id = 9199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trolljuju", description = "Die Körper der Trolle, die in den Amanikatakomben begraben wurden, sind wieder von den Toten auferstanden! Ich möchte, dass Ihr dorthin geht und mir einen Beweis für ihren endgültigen Tod bringt. Manche dieser Trollmumien, sowie ihre lebendigen Artgenossen, tragen Juju bei sich. Es handelt sich dabei um leuchtende Objekte, denen eine unbekannte Macht innewohnt. Wahrscheinlich ist es das, was sie am Leben erhält!\n\nDie Katakomben liegen im Sonnenhügel, direkt Richtung Osten. Man sagte mir, dass der einfachste Weg hinein an der Nordwand des Hügels liegt. Seht Euch dort um, {class}!", sourceObjective = "Sammelt 8 Trolljuju und bringt sie zu Todespirscher Maltendis in Tristessa in den Geisterlanden.", progress = "Ich muss Euch wohl nicht erst sagen, dass wir uns diesen Ärger mit den von den Toten auferstandenen Trollen hier bei uns kaum leisten können! Wir haben schon genug Probleme mit der Todesfestung im Süden!", completion = "Mumien, die von den Trollpriestern wiedererweckt werden... clever! Die Waldschattentrolle wollen ihre Reihen wohl mit Hilfe nekromantischer Mittel verstärken. Ich wette, dass diese Orakel das Juju bei ihrem Wiedererweckungsritual verwendet haben.\n\nIhr habt Eure Pflicht wieder einmal so erfüllt, wie es sich für einen {class} mit mehr und mehr Ansehen geziemt. Nehmt diesen Lohn als Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[9200] = { id = 9200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksverfügung - Erheblicher Manatrank", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer AL-473:\n\n10 erhebliche Manatränke.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", sourceObjective = "Bringt 10 erhebliche Manatränke und die Handwerksverfügung für die erheblichen Manatränke zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", progress = "Ihr führt einen Auftrag aus, {class}?", completion = "Die Nützlichkeit hiervon steht wohl außer Frage.", sourceObjectiveStatus = "unverified-source-field" }
quests[9201] = { id = 9201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksverfügung - Großer Arkanschutztrank", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer AL-1420:\n\n15 große Arkanschutztränke.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", sourceObjective = "Bringt 15 große Arkanschutztränke und die Handwerksverfügung für die großen Arkanschutztränke zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", progress = "Ihr führt einen Auftrag aus, {class}?", completion = "<Rottenkommandant Stonebruiser öffnet einen der großen Arkanschutztränke und nimmt einen kräftigen Schluck.>\n\nWooohooo! Das geht richtig ab, Baby! Aber richtig!", sourceObjectiveStatus = "unverified-source-field" }
quests[9202] = { id = 9202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksverfügung - Erheblicher Heiltrank", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer AL-169110:\n\n20 erhebliche Heiltränke.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", sourceObjective = "Bringt 20 erhebliche Heiltränke und die Handwerksverfügung für die erheblichen Heiltränke zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", progress = "Ihr führt einen Auftrag aus, {class}?", completion = "Wisst Ihr wie die hier von den Truppen an der Front genannt werden? Priester in der Flasche...\n\n<Rottenkommandant Stonebruiser singt.>\n\n\"I'm your priest in a bott-le baby... you gotta drink me the right way...\"\n\nWas glotzt Ihr so Junge? Der Titel war hier monatelang auf Platz Eins!", sourceObjectiveStatus = "unverified-source-field" }
quests[9203] = { id = 9203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksverfügung - Trank der Versteinerung", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer AL-90:\n\n1 Trank der Versteinerung.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", sourceObjective = "Bringt 1 Trank der Versteinerung und die Handwerksverfügung für den Trank der Versteinerung zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[9204] = { id = 9204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksverfügung - Steinschuppenaal", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer FS-5:\n\n40 Steinschuppenaale.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", sourceObjective = "Bringt 40 Steinschuppenaale und die Handwerksverfügung für die Steinschuppenaale zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", progress = "Ihr führt einen Auftrag aus, {class}?", completion = "Hier hättet hierfür eine andere Verwendung gehabt, nicht wahr? Nun ja, dem Ganzen nachzuweinen hilft auch nicht mehr, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9205] = { id = 9205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksverfügung - Panzerfisch", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer FS-12:\n\n30 Panzerfische.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", sourceObjective = "Bringt 30 Panzerfische und die Handwerksverfügung für die Panzerfische zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", progress = "Ihr führt einen Auftrag aus, {class}?", completion = "Ihr wisst wirklich nicht, wofür man die hier braucht?\n\n<Rottenkommandant Stonebruiser lacht.>\n\nAls ob ich Euch das verraten würde!", sourceObjectiveStatus = "unverified-source-field" }
quests[9206] = { id = 9206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksverfügung - Zitteraal", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer FS-9:\n\n30 Zitteraale.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", sourceObjective = "Bringt 30 Zitteraale und die Handwerksverfügung für die Zitteraale zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", progress = "Ihr führt einen Auftrag aus, {class}?", completion = "Aus denen macht man die besten Aalröllchen in der ganzen Welt. Richtig gehört - IN DER GANZEN WELT.", sourceObjectiveStatus = "unverified-source-field" }
quests[9207] = { id = 9207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grubenlichterzproben", description = "Ich wurde vom Sanktum der Sonne hierher geschickt, um ein paar Erzproben zu sammeln, aber die Gnolle haben diesen Ort überrannt! Mein Kopf wird noch auf dem Präsentierteller landen, wenn ich diese Proben nicht bald zum Magister bringe. Vielleicht könnt Ihr mir helfen, {class}?\n\nIhr findet das Erz in den Zinn- und Kupfervorkommen, aber auch die Gnolle tragen es mit sich herum. Sobald Ihr genug habt, bringt Ihr es zu Magister Quallestis beim Sanktum der Sonne, direkt östlich von hier. Überquert die Todesschneise, das Sanktum liegt genau südlich vom Sonnenhügel.", sourceObjective = "Sammelt 6 Einheiten Grubenlichterz und bringt sie zu Magister Quallestis beim Sanktum der Sonne in den Geisterlanden.", progress = "Wie kann ich Euch helfen, {class}?", completion = "Mein Lehrling konnte sich nicht selbst um diese Angelegenheit kümmern? Ich werde noch ein Wörtchen mit ihr zu reden haben, sobald sie wieder da ist, Gnolle hin oder her. Außerdem, warum ist sie nicht mit Euch zurückgekommen?\n\n<Der Magister seufzt.>\n\nSie ist eine schwierige Persönlichkeit und ihre Ausbildung wird mir noch helle Freude bereiten. Danke, dass Ihr mir diese Proben gebracht habt, {class}. Wir hoffen ein paar spezielle Eigenschaften darin zu entdecken, die uns im Kampf gegen die Geißel von Nutzen sein können.\n\nBitte nehmt diesen Lohn als Zeichen meiner Wertschätzung.", sourceObjectiveStatus = "unverified-source-field" }
quests[9208] = { id = 9208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Greuelwächter - Arkanum des Schutzes", description = "Zanza kann viele antike Trollverzauberungen mit den richtigen Komponenten herstellen! Habt Ihr von dem Greuelwächter gehört? Nein, natürlich nicht. Euer Geist wurde mit jämmerlicher Elfenmagie verwirrt.\n\nBringt mir ein Arkanum, wie es die Elfen herstellen, damit ich das Böse zerstören kann. Seid Ihr erfolgreich, so soll der Greuelwächter Euch gehören.", sourceObjective = "Zanza der Ruhelose in Zul'Gurub möchte ein Arkanum des Schutzes.", sourceObjectiveStatus = "unverified-source-field" }
quests[9209] = { id = 9209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Greuelwächter - Arkanum der Schnelligkeit", description = "Zanza kann viele antike Trollverzauberungen mit den richtigen Komponenten herstellen! Habt Ihr von dem Greuelwächter gehört? Nein, natürlich nicht. Euer Geist wurde mit jämmerlicher Elfenmagie verwirrt.\n\nBringt mir ein Arkanum, wie es die Elfen herstellen, damit ich das Böse zerstören kann. Seid Ihr erfolgreich, so soll der Greuelwächter Euch gehören.", sourceObjective = "Zanza der Ruhelose in Zul'Gurub möchte ein Arkanum der Schnelligkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[9210] = { id = 9210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Greuelwächter - Arkanum des Fokus", description = "Zanza kann viele antike Trollverzauberungen mit den richtigen Komponenten herstellen! Habt Ihr von dem Greuelwächter gehört? Nein, natürlich nicht. Euer Geist wurde mit jämmerlicher Elfenmagie verwirrt.\n\nBringt mir ein Arkanum, wie es die Elfen herstellen, damit ich das Böse zerstören kann. Seid Ihr erfolgreich, so soll der Greuelwächter Euch gehören.", sourceObjective = "Zanza der Ruhelose in Zul'Gurub möchte ein Arkanum des Fokus.", progress = "Habt Ihr das Arkanum?", completion = "Die wertlose Magie in diesen Verzauberungen verstärkt meinen Ärger. Mein Zorn gibt mir Stärke.\n\nBringt mir mehr davon und Ihr werdet einen weiteren Greuelwächter erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[9211] = { id = 9211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Eiswächter", description = "Ah, der Eiswächter. Es ist ein leichter Hauch schützender Magie, der bestimmte Teile der Ausrüstung bedeckt. Der Eiswächter verleiht jenen, die gegen Kreaturen von Frost und Eis kämpfen, erhöhten Schutz vor deren Angriffen.\n\nWie bei allem anderen auch, das vom Zornwirker hergestellt wird, so hat auch dieses Stück seinen Preis - einen Preis, der nicht diskutiert werden kann, wie viel Ihr Euch auch beklagen mögt. Interesse?", sourceObjective = "Mataus der Zornwirker bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte 10 Insignien des Kreuzzugs und 30 Gold.", progress = "Wäre es nicht für diese Argentumwachen, so wärt Ihr bereits ein Fleck auf diesem Boden.", completion = "<Mataus steckt das Gold in seine Taschen.>\n\nViel Spaß mit den Reparaturkoten, {race}. Naxxramas geht recht 'lieblos' mit Außenstehenden um.", sourceObjectiveStatus = "unverified-source-field" }
quests[9212] = { id = 9212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flucht aus den Katakomben", description = "Sehe ich so verängstigt aus, wie ich mich fühle? Diese Trolle haben mich aus dem Hinterhalt überfallen und in diesem Käfig gefangen gehalten. Ich glaube sie wollen mich opfern! Helft mir von hier zu fliehen!\n\nDas Schloss des Käfigs ist nicht allzu kompliziert... Ich kann es von dieser Seite nur nicht erreichen. Befreit mich und geleitet mich zurück zur Enklave der Weltenwanderer. Ich bin mir sicher, dass Hauptmann Helios Euch dafür entlohnen wird, außerdem wäre ich Euch für immer dankbar!", sourceObjective = "Begleitet Waldläuferin Lilatha zu Hauptmann Helios bei der Enklave der Weltenwanderer in den Geisterlanden.", completion = "Ihr seid ein ziemlicher Held, {class}, sie da lebend herausbekommen zu haben. Ich denke wir müssen einen Gegenschlag planen, um diese Katakomben auszuräuchern. Als wenn wir nicht schon genug Ärger mit den lebenden Trollen hätten!\n\nIhr habt heute außerordentlich gute Arbeit geleistet, Ihr verdient eine Belohnung. Sucht Euch etwas aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[9213] = { id = 9213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schattenwächter", description = "Das Machwerk eines Genies! Wie beim Eiswächter, ist es auch beim Schattenwächter ein leichter Hauch schützender Magie, der bestimmte Teile der Ausrüstung bedeckt. Der Schattenwächter wird Euch genauso wie der Eiswächter einen guten Batzen Geld kosten.\n\n<Mataus streckt seine Hand aus und reibt seine Finger aneinander.>\n\nInteresse?", sourceObjective = "Mataus der Zornwirker bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte 10 Insignien des Kreuzzugs und 30 Gold.", sourceObjectiveStatus = "unverified-source-field" }
quests[9214] = { id = 9214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Arsenal der Waldschattentrolle", description = "{class}, ich möchte, dass Ihr so viele Waldschattentrolle wie möglich erledigt. Wir müssen ihre Reihen so weit wie möglich ausdünnen, bevor wir uns der Todesfestung zuwenden können. Und wenn Ihr schon mal dabei seid, sollten wir gleich zwei Fliegen mit einer Klappe schlagen! Bringt einfach sämtliche Waffen mit, die Ihr bei den Trollen findet. Es wäre eine Verschwendung sie zusammen mit den Trollen verrotten zu lassen und wir könnten sie im Kampf gegen die Geißel einsetzen.\n\nErledigt ihre Lager im Osten und Süden bei Zeb'Tela und Zeb'Nowa.", sourceObjective = "Sammelt 3 Kopfjägeräxte, 3 Schattenzauberstreitkolben, 3 Klauen eines Pantherlords und 3 Verhexerstäbe. Bringt sie zu Hauptmann Helios bei der Enklave der Weltenwanderer in den Geisterlanden.", progress = "Habt Ihr die Waffen beschafft? Sobald wir die Reihen der Waldschattentrolle dezimiert haben, können wir uns wieder dem Kampf gegen die Geißel widmen.", completion = "Ich werde umgehend einige Waldläufer entsenden, um den Schaden, den Ihr unter den Waldschattentrollen angerichtet habt, zu begutachten. Wenn die von Euch mitgebrachte Waffensammlung auch nur ansatzweise den Erfolg Eures Angriffs gegen die Trolle widerspiegelt, sollten wir mit den Überlebenden leichtes Spiel haben. Das wird uns einen baldigen Angriff auf die Geißel ermöglichen.\n\nHier, nehmt diese Münze als Zeichen meiner Dankbarkeit, das schafft wieder etwas Platz in meinem Geldbeutel.", sourceObjectiveStatus = "unverified-source-field" }
quests[9215] = { id = 9215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt mir Kel'gashs Kopf!", description = "GESUCHT: Bringt den Kopf von Kel'gash dem Boshaften, Häuptling der Waldschattentrolle, zu Hauptmann Helios. Die Wahl der Mittel steht frei. Kel'gash soll sich irgendwo im Süden, in Zeb'Nowa, herumtreiben.\n\n\n\nBELOHNUNG: Ja, aber nicht im Voraus!", sourceObjective = "Bringt den Kopf von Kel'gash dem Boshaften zu Hauptmann Helios bei der Enklave der Weltenwanderer in den Geisterlanden.", progress = "Was ist das für ein widerlicher Gestank?", completion = "Ah, Kel'gashs Kopf ist der Quell dieses wundervollen Aromas. Ihr habt offensichtlich ganze Arbeit geleistet, {class}!\n\nDer Tod ihres Anführers hat die Waldschattentrolle ins Chaos gestürzt. Berücksichtigt man jetzt noch Eure letzten Einsätze zur Dezimierung ihrer Anzahl, denke ich, dass jetzt der Zeitpunkt für unsere Gegenoffensive gekommen ist, um sie ein für alle Mal zu vernichten.\n\nIhr habt meinen Dank, {name}. Kann ich Euch vielleicht für einen dieser Gegenstände begeistern?", sourceObjectiveStatus = "unverified-source-field" }
quests[9216] = { id = 9216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faulende Herzen", description = "Ich habe gehört, dass die Amanitrolle die Herzen ihrer Feinde essen, um deren Stärke zu stehlen. Sie könnten etwas im Schilde führen, {name}. Bereitet man sie richtig auf, kann man aus den Herzen der Untoten mächtige Elixiere gewinnen.\n\nJagt die Zombies in der Todesschneise und bringt mir ihre Herzen. Ich werde Euch die Art von Verstärkung zeigen, die wir Euren körperlichen Fähigkeiten im Kampf gegen die Untoten verleihen können.", sourceObjective = "Bringt 10 faulende Herzen zu Magistrix Aminel in Tristessa.", progress = "Habt Ihr die Zombieherzen, nach denen ich verlangt habe, {name}?", completion = "Nehmt dieses Gebräu, {name}. Sobald Ihr es getrunken habt, erfährt Eure körperliche Stärke im Kampf gegen die Geißel einen Schub. Wenn Ihr noch mehr von dieser Probe brauchen solltet, bringt mir mehr Herzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9217] = { id = 9217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr faulende Herzen", progress = "Habt Ihr mir noch mehr Zombieherzen gebracht? Ich kann so viele davon verarbeiten, wie Ihr mir besorgen könnt, {name}.", completion = "Dies wird Euch mit mehr Stärke im Kampf gegen die Geißel versorgen. Bringt mir mehr Herzen, falls Ihr welche findet, {name}." }
quests[9218] = { id = 9218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wirbelknochenstaub", description = "Die dunklen Energien, welche durch die Körper reanimierter Skelette fließen, reichern sich hauptsächlich in ihrer Wirbelsäule an. Ich habe eine Methode entdeckt, dank der man diese Energie in einen Trank mischen kann, der unsere magischen Fähigkeiten im Kampf gegen die Untoten verstärkt.\n\nBringt mir ein paar Einheiten Wirbelknochenstaub und ich werde Euch gerne eine Probe von dem Trank abgeben. Ihr könnt zahlreiche Skelette in der Todesschneise finden, westlich von hier.", sourceObjective = "Bringt 10 Einheiten Wirbelknochenstaub zu Magistrix Aminel in Tristessa.", progress = "Habt Ihr die Proben, nach denen ich verlangt habe, {name}?", completion = "Hier, für Euch, {name}. Ihr werdet den Unterschied sofort spüren!\n\nIhr könnt mir jeder Zeit mehr Wirbelknochenstaub bringen, ich kann so viele davon verarbeiten, wie Ihr mir besorgen könnt. Nebenwirkungen? Naja, Eure Stimme klingt ein bisschen höher, aber das sind lediglich die Rückstände des Staubs die verrückt spielen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9219] = { id = 9219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Wirbelknochenstaub" }
quests[9220] = { id = 9220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krieg gegen die Todesfestung", description = "Wenn Ihr unserer Sache dienen wollt, gibt es keinen besseren Ort und keinen idealeren Zeitpunkt, als das Hier und Jetzt.\n\nMit dem Wiederaufbau des Sanktums der Sonne haben wir das Banner des Widerstandes im Angesicht der Thronfeste unseres Feindes gehisst, kurz vor den Toren der Todesfestung.\n\nGeht und tötet die Horden der Untoten, die diesen finsteren Hort der Geißel bewohnen.", sourceObjective = "Tötet in der Todesfestung 5 Augen von Dar'khan, 6 nerubische Zenturio und 6 Wehklagende und kehrt anschließend zu Magister Idonis beim Sanktum der Sonne in den Geisterlanden zurück.", completion = "Die Geißel hat unsere Rache vernommen, {name}. Nicht mehr lange und ihre verfluchte Zitadelle wird in Trümmern liegen.\n\nJetzt, da sie geschwächt sind, ist es an der Zeit, strategisch günstige Ziele anzugreifen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9221] = { id = 9221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überragende Kampfausrüstung - Freund der Dämmerung", description = "Seid gegrüßt, Freund. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für mächtige Gegenstände einlösen würdet?\n\nIch muss Euch warnen, wer bei der Argentumdämmerung einen freundlichen Ruf genießt, muss sich bei Käufen mit einem hohen Aufpreis abfinden. Ich würde Euch raten, Euren Ruf bei der Argentumdämmerung erst einmal zu verbessern, bevor Ihr Eure Pläne weiterverfolgt.", sourceObjective = "Für 30 Insignien der Dämmerung und 30 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9222] = { id = 9222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Epische Kampfausrüstung - Freund der Dämmerung", description = "Seid gegrüßt, Freund. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für sehr mächtige Gegenstände einlösen würdet?\n\nIch muss Euch warnen, wer bei der Argentumdämmerung einen freundlichen Ruf genießt, muss sich bei Käufen mit einem extrem hohen Aufpreis abfinden. Ich würde Euch raten, Euren Ruf bei der Argentumdämmerung erst einmal zu verbessern, bevor Ihr Eure Pläne weiterverfolgt.", sourceObjective = "Für 110 Insignien der Dämmerung und 110 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9223] = { id = 9223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überragende Kampfausrüstung - Wohlwollen der Dämmerung", description = "Seid gegrüßt, Freund. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für mächtige Gegenstände einlösen würdet?\n\nIch muss Euch warnen, wer bei der Argentumdämmerung einen wohlwollenden Ruf genießt, muss sich bei Käufen mit einem ziemlich unerschwinglichen Aufpreis abfinden. Ich würde Euch raten, Euren Ruf bei der Argentumdämmerung erst einmal zu verbessern, bevor Ihr Eure Pläne weiterverfolgt.", sourceObjective = "Für 20 Insignien der Dämmerung und 20 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9224] = { id = 9224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Epische Kampfausrüstung - Wohlwollen der Dämmerung", description = "Seid gegrüßt, Freund. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für sehr mächtige Gegenstände einlösen würdet?\n\nIch muss Euch warnen, wer bei der Argentumdämmerung einen wohlwollenden Ruf genießt, muss sich bei Käufen mit einem extrem unerschwinglichen Aufpreis abfinden. Ich würde Euch raten, Euren Ruf bei der Argentumdämmerung erst einmal zu verbessern, bevor Ihr Eure Pläne weiterverfolgt.", sourceObjective = "Für 75 Insignien der Dämmerung und 75 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9225] = { id = 9225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Epische Kampfausrüstung - Respekt der Dämmerung", description = "Seid gegrüßt, Freund. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für sehr mächtige Gegenstände einlösen würdet?\n\nIch muss Euch warnen, wer bei der Argentumdämmerung einen respektvollen Ruf genießt, muss für epische Gegenstände noch immer einen sehr hohen Preis bezahlen. Ich würde Euch raten, Euren Ruf bei der Argentumdämmerung erst einmal zu verbessern, bevor Ihr Eure Pläne weiterverfolgt.", sourceObjective = "Für 45 Insignien der Dämmerung und 45 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9226] = { id = 9226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überragende Kampfausrüstung - Respekt der Dämmerung", description = "Seid gegrüßt, Freund. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für mächtige Gegenstände einlösen würdet?\n\nWer bei der Argentumdämmerung einen respektvollen Ruf genießt, kann Gegenstände zu einem recht angemessenem Preis erwerben. Ich würde Euch zu einem Geschäft raten!", sourceObjective = "Für 7 Insignien der Dämmerung und 7 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", progress = "Wählt mit Bedacht. Es gibt keine Rückerstattung.", completion = "Schönen Tag noch, {name}. Es war ein Vergnügen mit Euch Geschäfte zu machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9227] = { id = 9227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überragende Kampfausrüstung - Ehrfurcht der Dämmerung", description = "Seid gegrüßt, Freund. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für mächtige Gegenstände einlösen würdet?\n\nWer bei der Argentumdämmerung einen ehrfürchtigen Ruf genießt, erhält bei Käufen einen Preisnachlass. Ich würde Euch zu einem Geschäft raten!", sourceObjective = "Für 6 Insignien der Dämmerung und 6 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", progress = "Wählt mit Bedacht. Es gibt keine Rückerstattung.", completion = "Schönen Tag noch, {name}. Es war ein Vergnügen mit Euch Geschäfte zu machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9228] = { id = 9228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Epische Kampfausrüstung - Ehrfurcht der Dämmerung", description = "Seid gegrüßt, Freund. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für sehr mächtige Gegenstände einlösen würdet?\n\nWer bei der Argentumdämmerung einen ehrfürchtigen Ruf genießt, erhält bei Käufen garantiert den besten Preisnachlass. Ich würde Euch zu einem Geschäft raten.", sourceObjective = "Für 27 Insignien der Dämmerung und 27 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9229] = { id = 9229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ramaladnis Schicksal", description = "Ramaladni war ein Krieger der Bruderschaft; er war ein Schüler von Hochlord Mograine bevor die Dämmerung überhaupt existierte! Als ihn die Nachricht von Mograines Tod erreichte, wurde er von Wut und Hass überwältigt.\n\nVersteht bitte, {name}, wenn Wut und der Drang nach Vergeltung von jemandem Besitz ergreifen, hört er auf, ein Mensch zu sein, und wird stattdessen zur Verkörperung der Emotionen, die ihn beherrschen. Und so geschah es, dass Ramaladni, beseelt vom Geist der Vergeltung, Naxxramas betrat um Rache zu üben... und niemals zurückkehrte.\n\nBetretet Naxxramas und findet heraus, was mit Ramaladni geschah.", sourceObjective = "Betretet Naxxramas und bringt Ramaladnis Schicksal in Erfahrung.", progress = "Gibt es Neuigkeiten über Ramaladni?", completion = "Es ist sein Ring! Aber er ist zerstört. Ihr habt keine weiteren Hinweise auf Ramaladni gefunden?\n\n<Korfax verzieht das Gesicht.>\n\nDas verheißt nichts Gutes für Ramaladni. Der Ring jedoch ... er könnte noch nützlich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[9230] = { id = 9230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ramaladnis eisiger Griff", description = "Den Ring wiederherzustellen, scheint eine ziemliche Herausforderung zu sein, {name}. Seht ihr, er wurde hergestellt aus Runen, die sich in Bauwerken der Geißel finden - in Bauwerken wie Naxxramas. Es könnten noch weitere Materialien gebraucht werden, aber Eure Hauptsorge sollte es sein, diese gefrorenen Runen zu beschaffen. Ich kann dem Ring seinen alten Glanz zurückgeben, wenn ihr mir bringt, was ich dazu benötige.", sourceObjective = "Korfax bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte, dass Ihr ihm 1 gefrorene Rune, 1 blauen Saphir und 1 Arkanitbarren bringt.", progress = "Gefrorene Runen findet man wahrscheinlich in Naxxramas.", completion = "Ramaladni selbst könnte es nicht besser gemacht haben! Hier ist der Ring, wie versprochen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9232] = { id = 9232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Einzige, das ich kann...", description = "Ihr haltet Euch für einen Helden der Dämmerung, ja? Ich habe gesehen, wie unsere besten Soldaten von Kel'Thuzads Gefolgsleuten überrannt wurden. Wie könnte jemand, der so ahnungslos ist wie Ihr, in Naxxramas bestehen?\n\n<Wilhelm seufzt.>\n\nPah, was für eine Wahl habe ich denn? Ihr seid das Beste, das ich zur Verfügung habe; warum sollte ich Euch nicht helfen?\n\nOmarion hat mir einen Plan hinterlassen. Es ist das Einzige, das ich kann... Ich kann ein paar Varianten dieser Hosen herstellen, Ihr müsst mich nur mit den Materialien versorgen.", sourceObjective = "Handwerker Wilhelm bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte, dass Ihr ihm 2 gefrorene Runen, 2 Essenzen des Wassers, 2 blaue Saphire und 30 Goldstücke bringt.", progress = "Ihr habt nicht zufällig Omarion getroffen?", completion = "<Wilhelm wischt sich den Schweiß von der Stirn.>\n\nDas war ein hartes Stück Arbeit! Ich hoffe, die Hose gefällt Euch, {class}. Zumindest werdet ihr jetzt in einer sauberen Hose sterben.", sourceObjectiveStatus = "unverified-source-field" }
quests[9233] = { id = 9233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Omarions Leitfaden", description = "Wilhelm,\n\nsolltet Ihr das hier lesen, bin ich bereits tot - endlich. Ihr sollt wissen, dass meine letzten Gedanken vor dem Tod Euch und Eurer Unfähigkeit als Handwerker galten. Unglücklicherweise besitzt der Überbringer dieses Leitfadens noch weniger Geschick als Ihr.\n\nZu dem Buch: Es beinhaltet meine letzten Anleitungen. Fertigt dem Überbringer dieses Leitfadens an, was immer dieser wünschen mag. Ich bin mir sicher, dass Ihr ein saftiges Honorar für Eure Dienste verlangen werdet, denn im Grunde seid Ihr nun mal ein Gauner.\n\nVerachtungsvoll,\n\nOmarion", sourceObjective = "Bringt Omarions Leitfaden zu Handwerker Wilhelm bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", progress = "Ist es das, was ich denke?\n\n<Wilhelm scheint begierig zu sein.>", completion = "Hey, der muss ja nicht ganz dicht gewesen sein, als er das geschrieben hat! Omarion und ich - wir waren die dicksten Freunde!\n\nEgal, dies hier eröffnet mit Sicherheit ein paar neue Möglichkeiten, {name}. Ich kann jetzt mehr Gegenstände anfertigen - natürlich gegen eine kleine Gebühr und Kosten für das Material.", sourceObjectiveStatus = "unverified-source-field" }
quests[9234] = { id = 9234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisfluchstulpen", description = "Dank Euch und Omarion, möge er in Frieden ruhen, bin ich nun im Stande, Eisfluchstulpen herzustellen. Ihr müsst mir lediglich die Materialien dafür bringen und eine geringe Handwerksgebühr zahlen.", sourceObjective = "Handwerker Wilhelm bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte 5 gefrorene Runen, 12 Thoriumbarren, 2 Arkanitbarren, 2 Essenzen des Wassers und 200 Gold.", sourceObjectiveStatus = "unverified-source-field" }
