quests[9286] = { id = 9286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scryers Faction Test" }
quests[9287] = { id = 9287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildung zum Paladin", sourceObjective = "Es erfüllt mich mit Stolz, dass Ihr mit mir sprechen möchtet. Früher war ich für die Ausbildung junger Paladine, die unserem Orden beitreten wollten, verantwortlich. Eine Pflicht und ein Privileg, das ich fraglos noch einmal auf mich nehme. Man spricht von Euch als jemand, der Gutes im Namen des Lichts tun möchte. Es wäre eine Ehre für mich, wenn ich Euch die ersten Schritte auf dem Weg eines Paladins lehren dürfte.\n\nSollen wir beginnen?", sourceObjectiveStatus = "unverified-source-field" }
quests[9288] = { id = 9288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildung zum Jäger", sourceObjective = "Ich bin froh, dass Ihr zu mir gekommen seid. Ich bin schon eine ganze Weile für die Ausbildung junger {class} verantwortlich, eine Aufgabe, die ich auch in dieser neuen Welt noch weiter erfüllen möchte. Ich beobachte Euch bereits seit geraumer Zeit und es wäre eine Ehre für mich, wenn ich Euch die Künste des Jägers lehren dürfte.\n\nSollen wir beginnen?", sourceObjectiveStatus = "unverified-source-field" }
quests[9289] = { id = 9289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildung zum Krieger", sourceObjective = "Es ist gut, dass Ihr meine Weisung ersucht. Ich habe seit Jahrhunderten junge Draeneikrieger ausgebildet, also werde ich Euch schon auf die eine oder andere Weise auf den richtigen Weg eines Kriegers verhelfen können. Ich sehe eine Zukunft als mächtiger Krieger für Euch voraus, aber nur, wenn Ihr auch wirklich beherzigt, was ich Euch beibringe.\n\nSeid Ihr bereit, junger Krieger?", sourceObjectiveStatus = "unverified-source-field" }
quests[9290] = { id = 9290, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildung zum Magier", sourceObjective = "Es ehrt mich, dass Ihr mich wegen meines Wissens aufsucht. Es gibt viel zu tun, wenn sich Eure magischen Fähigkeiten gänzlich entfalten sollen.\n\nSeit mehr als hundert Jahren lehre ich die Künste der arkanen Magie, Frost- und Feuerzauber. Auch auf dieser Welt kann ich ihre Macht spüren. Möchtet Ihr, dass ich Euch an meinen Kenntnissen teilhaben lasse?", sourceObjectiveStatus = "unverified-source-field" }
quests[9291] = { id = 9291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildung zum Priester" }
quests[9292] = { id = 9292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesprungener nekrotischer Kristall", description = "Ihr entdeckt beim Körper der toten Monstrosität einen gesprungenen Kristall, der langsam mit nekrotischer Energie pulsiert.", sourceObjective = "Bringt den gesprungenen nekrotischen Kristall zu Leutnant Orrin außerhalb der Tore von Sturmwind.", progress = "Ja, was gibt's?", completion = "Hm, Ihr habt das beim Körper einer der Monstrositäten gefunden?\n\nWir haben von Basislagern der Nekropole gehört, die die Geißel heraufbeschworen hat. Ich vermute, dass sie eines davon innerhalb von Stormwind errichten wollten. Es ist gut, dass sie damit erfolglos waren.", sourceObjectiveStatus = "unverified-source-field" }
quests[9293] = { id = 9293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was getan werden muss...", description = "Der nahegelegene See wurde von einem Energiekristall des Schiffs verseucht. Zahlreiche Pflanzen und Tiere des Am'mentals sind deswegen mutiert.\n\nIch habe bereits eine Theorie aufgestellt, wie man den See heilen kann, allerdings brauche ich Proben von mutierten Wurzelpeitschern für eine Auswertung. Man findet sie im Westen der Am'menfelder.\n\nWerdet Ihr mir helfen, {class}?", sourceObjective = "Sammelt 10 Peitscherproben ein und bringt sie zu Botanikerin Taerix bei der Absturzstelle im Am'mental.", progress = "Der Zustand aller Proben muss einwandfrei sein, damit wir eine Chance haben, den See zu entseuchen.\n\nUns bleibt nicht viel Zeit, {class}!", completion = "Genau das habe ich gebraucht. Danke, {class}!\n\nWährend Ihr unterwegs wart, habe ich bereits meine Ausrüstung aufgebaut, um die Proben auswerten zu können. Ich sollte lediglich ein paar Augenblicke benötigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9294] = { id = 9294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Heilung des Sees", description = "Dem Licht sei Dank, ich glaube es wird funktionieren! Ich habe einen Wirkstoff, den Ihr beim Silberwellensee im Süden einsetzen müsst. Er wird den Effekt des strahlenden Energiekristalls des Schiffs, der hier heruntergestürzt ist, neutralisieren.\n\nSchwimmt raus auf den See und verwendet dort den Neutralisierungswirkstoff. Keine Sorge, Ihr werdet der Strahlung nicht lange genug ausgesetzt sein, um verseucht zu werden.", sourceObjective = "Verwendet den Neutralisierungswirkstoff bei dem strahlenden Energiekristall und kehrt anschließend zu Botanikerin Taerix bei der Absturzstelle im Am'mental zurück.", completion = "Euren Schilderungen zufolge hat der Neutralisierungswirkstoff funktioniert! Ich wünschte nur, ich wüsste, wie lange er anhält. Wir müssen den Energiekristall gänzlich aus dem See entfernen.\n\nDanke, {name}! Ich werde Tedon bitten, den Neutralisierungswirkstoff sofort an einem der gefangenen Tiere auszuprobieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[9295] = { id = 9295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brief von der Front", description = "Ihr habt dieses Schreiben bei einem der zahlreichen Diener der Geißel gefunden, die Ihr getötet habt. Sein Äußeres und der Geruch lassen darauf schließen, dass es sich schon seit längerem im Besitz des Untoten befunden haben muss. Vielleicht wäre ja jemand bei der Kapelle des hoffnungsvollen Lichts an einer weiteren Untersuchung interessiert...", sourceObjective = "Bringt den zerfledderten Brief zum Bewahrer der Schriften bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", progress = "Ja? Was habt Ihr denn da?", completion = "Wie tragisch. Diese Zeilen, die eindeutig für jemanden bestimmt waren, den der Soldat liebte, haben ihren Empfänger nie erreicht. Die beschriebenen Geschehnisse haben sich vor Jahren ereignet; Ich weiß nicht, ob der bestimmte Empfänger noch lebt.\n\nMan kann jedoch noch hoffen. Anhand des angegebenen Namens und der enthaltenen Informationen, könnte ich die Familie vielleicht noch ausfindig machen! Es wird einiges an Nachforschungen bedürfen, aber der Bibliothekar in Stormwind ist mir noch einen Gefallen schuldig...\n\nDanke für diesen Dienst. Mit Eurer Hilfe findet womöglich noch jemand seinen verdienten Seelenfrieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9296] = { id = 9296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "reuse" }
quests[9297] = { id = 9297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "reuse" }
quests[9298] = { id = 9298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "reuse" }
quests[9299] = { id = 9299, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Notiz von der Front", description = "Ihr habt dieses Schreiben bei einem der zahlreichen Diener der Geißel gefunden, die Ihr getötet habt. Sein Äußeres und der Geruch lassen darauf schließen, dass es sich schon seit längerem im Besitz des Untoten befunden haben muss. Vielleicht wäre ja jemand bei der Kapelle des hoffnungsvollen Lichts an einer weiteren Untersuchung interessiert...", sourceObjective = "Bringt die verblichene Notiz zum Bewahrer der Schriften bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", progress = "Ja? Was habt Ihr denn da?", completion = "Wie tragisch. Diese Zeilen, die eindeutig für jemanden bestimmt waren, den der Soldat liebte, haben ihren Empfänger nie erreicht. Die beschriebenen Geschehnisse haben sich vor Jahren ereignet; Ich weiß nicht, ob der bestimmte Empfänger noch lebt.\n\nMan kann jedoch noch hoffen. Anhand des angegebenen Namens und der enthaltenen Informationen, könnte ich die Familie vielleicht noch ausfindig machen! Es wird einiges an Nachforschungen bedürfen, aber der Bibliothekar in Stormwind ist mir noch einen Gefallen schuldig...\n\nDanke für diesen Dienst. Mit Eurer Hilfe findet womöglich noch jemand seinen verdienten Seelenfrieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9300] = { id = 9300, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seite von der Front", description = "Ihr habt dieses Schreiben bei einem der zahlreichen Diener der Geißel gefunden, die Ihr getötet habt. Sein Äußeres und der Geruch lassen darauf schließen, dass es sich schon seit längerem im Besitz des Untoten befunden haben muss. Vielleicht wäre ja jemand bei der Kapelle des hoffnungsvollen Lichts an einer weiteren Untersuchung interessiert...", sourceObjective = "Bringt die zerfranste Seite zum Bewahrer der Schriften bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", progress = "Ja? Was habt Ihr denn da?", completion = "Wie tragisch. Diese Zeilen, die eindeutig für jemanden bestimmt waren, den der Soldat liebte, haben ihren Empfänger nie erreicht. Die beschriebenen Geschehnisse haben sich vor Jahren ereignet; Ich weiß nicht, ob der bestimmte Empfänger noch lebt.\n\nMan kann jedoch noch hoffen. Anhand des angegebenen Namens und der enthaltenen Informationen, könnte ich die Familie vielleicht noch ausfindig machen! Es wird einiges an Nachforschungen bedürfen, aber der Bibliothekar in Stormwind ist mir noch einen Gefallen schuldig...\n\nDanke für diesen Dienst. Mit Eurer Hilfe findet womöglich noch jemand seinen verdienten Seelenfrieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9301] = { id = 9301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umschlag von der Front", description = "Ihr habt dieses Schreiben bei einem der zahlreichen Diener der Geißel gefunden, die Ihr getötet habt. Sein Äußeres und der Geruch lassen darauf schließen, dass es sich schon seit längerem im Besitz des Untoten befunden haben muss. Vielleicht wäre ja jemand bei der Kapelle des hoffnungsvollen Lichts an einer weiteren Untersuchung interessiert...", sourceObjective = "Bringt den blutbefleckten Umschlag zum Bewahrer der Schriften bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", progress = "Ja? Was habt Ihr denn da?", completion = "Wie tragisch. Diese Zeilen, die eindeutig für jemanden bestimmt waren, den der Soldat liebte, haben ihren Empfänger nie erreicht. Die beschriebenen Geschehnisse haben sich vor Jahren ereignet; Ich weiß nicht, ob der bestimmte Empfänger noch lebt.\n\nMan kann jedoch noch hoffen. Anhand des angegebenen Namens und der enthaltenen Informationen, könnte ich die Familie vielleicht noch ausfindig machen! Es wird einiges an Nachforschungen bedürfen, aber der Bibliothekar in Stormwind ist mir noch einen Gefallen schuldig...\n\nDanke für diesen Dienst. Mit Eurer Hilfe findet womöglich noch jemand seinen verdienten Seelenfrieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9302] = { id = 9302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schreiben von der Front", description = "Ihr habt dieses Schreiben bei einem der zahlreichen Diener der Geißel gefunden, die Ihr getötet habt. Sein Äußeres und der Geruch lassen darauf schließen, dass es sich schon seit längerem im Besitz des Untoten befunden haben muss. Vielleicht wäre ja jemand bei der Kapelle des hoffnungsvollen Lichts an einer weiteren Untersuchung interessiert...", sourceObjective = "Bringt das zerknitterte Schreiben zum Bewahrer der Schriften bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", progress = "Ja? Was habt Ihr denn da?", completion = "Wie tragisch. Diese Zeilen, die eindeutig für jemanden bestimmt waren, den der Soldat liebte, haben ihren Empfänger nie erreicht. Die beschriebenen Geschehnisse haben sich vor Jahren ereignet; Ich weiß nicht, ob der bestimmte Empfänger noch lebt.\n\nMan kann jedoch noch hoffen. Anhand des angegebenen Namens und der enthaltenen Informationen, könnte ich die Familie vielleicht noch ausfindig machen! Es wird einiges an Nachforschungen bedürfen, aber der Bibliothekar in Stormwind ist mir noch einen Gefallen schuldig...\n\nDanke für diesen Dienst. Mit Eurer Hilfe findet womöglich noch jemand seinen verdienten Seelenfrieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9303] = { id = 9303, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immunisierung", description = "Zhanaa braucht unsere Hilfe, um Teile aus der Exodar zu bergen. Taerix hat eine Immunisierungsmethode vorbereitet, mit der die Nisteleulkins behandelt werden können. Sie bewohnen die Gegend, in der die meisten Teile gefunden werden können.\n\nNähert Euch den noch nicht verseuchten Biestern und wendet den Kristall auf sie an. Die anderen müsst Ihr leider umbringen. Ihr findet sie im Nisteldickicht und bei den Nistelhügeln im Südosten.", sourceObjective = "Wendet den Immunisierungskristall auf 6 Nisteleulkin an. Kehrt anschließend zu Verteidiger Aldar bei der Absturzstelle im Am'mental zurück.", progress = "Je mehr wir tun können, um den Nistelwald aufzuräumen, desto schneller kann Zhanaa zurück an die Arbeit.", completion = "Da jetzt viele der Eulkin immunisiert wurden, können wir uns auf unseren Aufbruch von hier konzentrieren, ohne die gesamte Eulkinpopulation ausrotten zu müssen.\n\nHier, sucht Euch etwas aus. Ihr habt eine so wunderbare Arbeit geleistet, Ihr verdient eine Belohnung!", sourceObjectiveStatus = "unverified-source-field" }
quests[9304] = { id = 9304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dokument von der Front", description = "Ihr habt dieses Schreiben bei einem der zahlreichen Diener der Geißel gefunden, die Ihr getötet habt. Sein Äußeres und der Geruch lassen darauf schließen, dass es sich schon seit längerem im Besitz des Untoten befunden haben muss. Vielleicht wäre ja jemand bei der Kapelle des hoffnungsvollen Lichts an einer weiteren Untersuchung interessiert...", sourceObjective = "Bringt das verschmierte Dokument zum Bewahrer der Schriften bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", progress = "Ja? Was habt Ihr denn da?", completion = "Wie tragisch. Diese Zeilen, die eindeutig für jemanden bestimmt waren, den der Soldat liebte, haben ihren Empfänger nie erreicht. Die beschriebenen Geschehnisse haben sich vor Jahren ereignet; Ich weiß nicht, ob der bestimmte Empfänger noch lebt.\n\nMan kann jedoch noch hoffen. Anhand des angegebenen Namens und der enthaltenen Informationen, könnte ich die Familie vielleicht noch ausfindig machen! Es wird einiges an Nachforschungen bedürfen, aber der Bibliothekar in Stormwind ist mir noch einen Gefallen schuldig...\n\nDanke für diesen Dienst. Mit Eurer Hilfe findet womöglich noch jemand seinen verdienten Seelenfrieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9305] = { id = 9305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ersatzteile", description = "Wir konnten einen beschädigten holografischen Emitter nach dem Absturz bergen. Sollten wir ihn reparieren können, besteht die Möglichkeit, dass wir noch andere Überlebende außerhalb des Am'mentals finden.\n\nVon dem Schiff hätte man einige Apparaturen sichern können, die geeignete Ersatzteile geliefert hätten, aber die heimischen Eulkin haben sie verschleppt, bevor wir sie überhaupt erreichen konnten.\n\n{name}, Ihr müsst ins Nisteldickicht und in die Nistelhügel im Süden gehen und die Ersatzteile zurückholen!", sourceObjective = "Beschafft 4 Emitterersatzteile und kehrt anschließend zu Technikerin Zhanaa bei der Absturzstelle im Am'mental zurück.", progress = "Ich bin mir sicher, dass wir den Emitter mit den Ersatzteilen reparieren können! Mit etwas Glück, werden wir da draußen noch andere finden, mit denen wir uns in Verbindung setzen können.", completion = "Lasst mich mal sehen.\n\nJa, ich denke, das wird gehen; gute Arbeit, {name}! Der Emitter ist ziemlich komplex und deshalb kann die Reparatur ein Weilchen dauern. Ich sage Euch Bescheid, sobald ich fertig bin.\n\nSchaut in der Zwischenzeit bei Verteidiger Aldar vorbei und fragt ihn, ob er Euch brauchen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[9309] = { id = 9309, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Späher", description = "Verschiedene Quellen konnten uns nun bestätigen, dass beim Schattenkamm ungewöhnliche Dinge vor sich gehen.\n\nDas ist äußerst beunruhigend, denn wir dachten, dass die bisherigen Aufklärungsmissionen gründlich genug gewesen wären. Einer meiner Späher hat sich noch nicht zurückgemeldet.\n\n{class}, Ihr müsst für mich Richtung Südwesten gehen, zur anderen Uferseite des Silberwellensees, und Tolaan finden. Findet heraus, was ihn aufgehalten hat.", sourceObjective = "Sprecht mit Tolaan im Schattenkamm im Am'mental.", completion = "Hilfe... Blutelfen! Ein... ein Hinterhalt. Ich habe... nicht mehr lange...", sourceObjectiveStatus = "unverified-source-field" }
quests[9310] = { id = 9310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwacher nekrotischer Kristall", description = "Ihr findet beim Körper der toten Kreatur einen Kristall, der schwache nekrotische Energie ausstrahlt.", sourceObjective = "Bringt den schwachen nekrotischen Kristall zu Leutnant Rukag im Hof von Unterstadt.", progress = "Kann ich Euch irgendwie weiterhelfen?", completion = "Ihr sagt, dass Ihr das bei einer der Kreaturen gefunden habt, die die Stadt angreifen?\n\nWir haben von Basislagern der Nekropole gehört, die die Geißel heraufbeschworen hat. Ich vermute, dass sie eines davon innerhalb von Undercity errichten wollten. Wir müssen zukünftig sehr vorsichtig sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[9311] = { id = 9311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutelfenspionage", description = "Ich habe einen Plan. Wir müssen ihren Anführer umbringen. Vielleicht ziehen sie sich ohne ihren Meister zurück, um sich neu zu formieren. Wir müssen Zeit schinden, damit wir die Reparaturen abschließen können.\n\nVerteidiger Aldar muss davon erfahren. Tötet die Gutachterin und kehrt dann zu ihm zurück, um ihn zu erzählen, was wir herausgefunden haben.", sourceObjective = "Tötet Gutachterin Kandress und informiert anschließend Verteidiger Aldar bei der Absturzstelle im Am'mental über die Ereignisse.", completion = "Danke, dass Ihr Euch um die Gutachterin gekümmert habt. Sie war ganz sicher ihre Anführerin. Ich versichere Euch, dass wir uns um den restlichen Haufen, der sich eventuell noch hier in der Nähe aufhält, kümmern werden.\n\nBitte, nehmt eine dieser Waffen als Zeichen unserer Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[9312] = { id = 9312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Emitter", description = "{name}, während Ihr den Schattenkamm erkundet habt, hat Zhanaa weiter am holografischen Emitter gearbeitet. Vielleicht solltet Ihr mit ihr sprechen.", sourceObjective = "Sprecht mit Technikerin Zhanaa bei der Absturzstelle im Am'mental.", completion = "Ja, ja! Ich glaube, ich habe den Emitter reparieren können! Hier, ich muss lediglich den letzten Kristall aktivieren und das sollte es gewesen sein.\n\nSeht, {name}, der Emitter. Er scheint zu funktionieren... es erscheint jemand!", sourceObjectiveStatus = "unverified-source-field" }
quests[9313] = { id = 9313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise zur Azurwacht", description = "Soweit so gut, {name}, Ihr müsst allerdings sofort zur Azurwacht reisen und mit Dyvuun sprechen!\n\nEs gibt einen Pfad, der westlich von dieser winzigen Insel führt. Folgt ihm und überquert den Kristallfluss, um auf den größeren Teil der Insel zu gelangen. Wenn Ihr dem Pfad noch weiter folgt, solltet Ihr die Azurwacht finden.\n\nVielleicht könnt Ihr sie ja überzeugen, uns etwas Hilfe und Vorräte zukommen zu lassen. Wir kommen nach, sobald wir können.\n\nIch danke Euch, ohne Euch hätten wir das nicht geschafft!", sourceObjective = "Sprecht mit Techniker Dyvuun bei der Azurwacht auf der Azurmythosinsel.", completion = "Ah, es ist gut, Euch wiederzusehen! Ich bin froh, dass wir beide unsere Emitter reparieren konnten, sonst hätten wir uns wohl nie gefunden. Sorgt Euch nicht, wir werden natürlich Hilfe und Vorräte ins Am'mental schicken.\n\nDa wir gerade von Hilfe sprechen... jetzt wo Ihr hier seid, könnt Ihr Euch ja mal umsehen und Euch bei den anderen vorstellen. Ich weiß, dass es jede Menge zu tun gibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9314] = { id = 9314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht von der Azurwacht", description = "{class}! Ein paar dieser mutierten Biester haben mich angesprungen und jetzt ist mein Bein verletzt.\n\nNachdem wir von Zhanaa gehört hatten, wurde ich von der Azurwacht auf eine Spähmission geschickt. Könntet Ihr vielleicht an meiner statt mit Versorgerin Chellan sprechen? Sie muss wissen, wie viele Leute sie in der Azurwacht erwarten soll. Ihr müsst lediglich den Kristallfluss hier überqueren und dem Pfad bis zur Azurwacht folgen.\n\nVergesst nicht, nach einer Unterkunft zu fragen, wenn Ihr dort seid.", sourceObjective = "Sprecht mit Versorgerin Chellan bei der Azurwacht auf der Azurmythosinsel.", completion = "Oh, Ihr müsst einer der Überlebenden sein, von denen wir gehört haben!\n\nIch bin froh, dass Ihr gekommen seid. Keine Sorge, wir schicken jemanden los, der sich Aeuns verletztes Bein ansehen wird.\n\nIch will unbedingt alles über Eure aufregende Überlebensgeschichte hören! Wenn Ihr bis hierher gekommen seid, müsst Ihr sehr tapfer sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[9315] = { id = 9315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anok'suten", description = "Kommt näher, ich... ich sterbe.\n\nMan entsandte mich hierher, um... um die Neruber zu besiegen, doch Vandril konnte nicht ahnen, dass sie... sie eine Anführerin haben.\n\n<Der sterbende Blutelf spuckt etwas Blut.>\n\nIhr müsst Anok'suten finden und... und töten. Sie wandert in der Umgebung von... Sonnenkuppe umher.", sourceObjective = "Tötet Anok'suten und kehrt anschließend zu Arkanist Vandril in Tristessa in den Geisterlanden zurück.", completion = "Ich muss mich für die schlechte Aufklärung entschuldigen, {class}. Hätte ich vorher etwas von der Existenz dieser Anok'suten gewusst, hätte ich Euch natürlich umgehend davon in Kenntnis gesetzt.\n\nUnsere Kräfte sind einfach zu weit verteilt und manche Dinge schlüpfen uns unter diesen Umständen einfach durchs Netz.", sourceObjectiveStatus = "unverified-source-field" }
quests[9316] = { id = 9316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wilde Goblins", description = "<Brianna schaut Euch prüfend an.>\n\nIhr wollt also ein paar Goblins töten, was? Nun, wenn Ihr dazu bereit seid, könnt Ihr mit den Wilden in der Nähe anfangen. Bringt mir ihre Zähne als Beweis Eurer Taten.", sourceObjective = "Brianna Schneider auf der Designerinsel möchte, dass Ihr ihr 10 Goblinzähne bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9317] = { id = 9317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geweihte Wetzsteine", progress = "Wenn Ihr mir acht nekrotische Runen von den Geißelinvasoren besorgt, kann ich Euch einen geweihten Wetzstein dafür geben. Er sollte Euch im Kampf gegen die Diener des Lichkönigs eine große Hilfe sein.", completion = "Danke, {name}. Hier ist Euer geweihter Wetzstein. Verwendet ihn weise." }
quests[9318] = { id = 9318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesegnetes Zauberöl", progress = "Die Argentumdämmerung wird Euch im Tausch gegen die nekrotischen Runen der Geißelinvasoren eine Phiole gesegnetes Zauberöl geben.", completion = "Ich hoffe, dass Ihr in Euren zukünftigen Schlachten davon Gebrauch machen könnt." }
quests[9319] = { id = 9319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Licht im Dunkeln", description = "Wir sind nicht die Einzigen, die dieses Fest feiern, {name}. Die Flamme ist ein wichtiger Bestandteil aller Lebewesen, aller Kulturen. Selbst an den dunkelsten Orten beginnen die Feuer zu leuchten.\n\nWenn Ihr dergleichen sehen möchtet, so wagt Euch in die Tiefe. Sucht nach den Freudenfeuern in Stratholme, Scholomance, bei den Ogern des Düsterbruchs und in den Hallen der Schwarzfelsspitze selbst. Ich erwarte Eure Rückkehr.", sourceObjective = "Findet und berührt die Freudenfeuer innerhalb der Schwarzfelsspitze, dem Düsterbruch, Scholomance und Stratholme. Kehrt dann zum Flammenbewahrer zurück.", progress = "Habt Ihr Euch im Dunkeln zurechtgefunden?", completion = "Euer Wesen erstrahlt mit der Energie der Flammen, die Ihr gefunden habt, {name}. Das Feuer, mit dem Ihr in Berührung gekommen seid,  ist mächtig. Mit dem richtigen Wissen, kann man sich diese Macht zu Nutzen machen...\n\n\n\nAh! Soweit so gut. Ich hoffe dies wird Euren Weg erleuchten, wohin immer Ihr auch gehen mögt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9320] = { id = 9320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erstklassiger Manatrank", progress = "Neben unseren anderen Vorräten verfügen wir auch über eine gewisse Zahl an erheblichen Manatränken, die für Euch von Nutzen sein könnten. Ich werde Euch einen im Tausch gegen fünfzehn nekrotische Runen geben.", completion = "Bitte sehr, {name}. Seid vorsichtig da draußen. Wir sind zu wenige, als dass wir uns viele Verluste auf dem Schlachtfeld leisten könnten." }
quests[9321] = { id = 9321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erstklassiger Heiltrank" }
quests[9322] = { id = 9322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glühende Feuer in Kalimdor", description = "Die Freudenfeuer des Sonnenwendfests werden überall in Azeroth gefeiert, die mannigfaltigen Länder Kalimdors sind dabei keine Ausnahme. Ihr scheint mir tauglich für eine Reise - wie wäre es mit einem Ausflug?\n\nDas Sonnenwendfest ist erst dann ein Ereignis, wenn man die blau glühenden Feuer in der Welt gesehen hat. Die Feiernden haben Feuer im eisigen Westen von Winterquell, im Nordosten von Azshara, in der Nähe der Heldenwacht in Silithus und beim Eingang zum üppigen Krater von Un'Goro entzündet. Kehrt zu mir zurück, sobald Ihr die Reise beendet habt.", sourceObjective = "Sucht die Lager des Sonnenwendfests in Azshara, Silithus, dem Krater von Un'Goro und Winterquell auf. Kehrt dann zum Flammenbewahrer zurück.", completion = "Euer Geist erstrahlt mit der Wärme der Feuer Kalimdors. Ist die Hitze nicht anregend?\n\nWenn die Macht von Euch schwindet, könnte Euch dies hier vielleicht dabei helfen, das Ganze wieder aufleben zu lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9323] = { id = 9323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glühende Feuer in den östlichen Königreichen", description = "Das Fest der Flamme ist im ganzen Land verbreitet, {class}. Kein Ort bleibt von der Wärme dieses Ereignisses unberührt, und die prächtigsten Feuer lodern in einem strahlenden Blau. Sucht nach ihnen.\n\nEines befindet sich genau nördlich von der Schwarzfelsspitze. Die anderen liegen tief im Innern der östlichen Pestländer, in der Nähe eines verfallenen Dorfes; entlang der Straße, die zu den Klippen im bergigen Hinterland führt, und auf dem Weg zu dem Dunklen Portal in den verwüsteten Landen.\n\nKehrt anschließend zu mir zurück.", sourceObjective = "Reist zu den Lagern des Sonnenwendfests in den verwüsteten Landen, den östlichen Pestländern, dem Hinterland und der sengenden Schlucht. Kehrt dann zum Flammenbewahrer zurück.", completion = "Ah, da seid Ihr also. Etwas erschöpfter, ein wenig schmutziger, aber erleuchtet! Die Wärme berührt und vereint uns alle während dieser Zeit. Euer Wesen erstrahlt mit der Macht der Feuer, die Ihr berührt habt.\n\nAh, ich vermute, dass Erleuchtung heutzutage wohl eher als eine armselige Belohnung für eine Aufgabe wie diese angesehen wird. Nehmt dies hier, bitte, und genießt das Fest.", sourceObjectiveStatus = "unverified-source-field" }
quests[9324] = { id = 9324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raubt die Flamme von Orgrimmar", description = "Die Flamme, die aus dem Zentrum von Orgrimmar entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Meister der Lehren könnte vielleicht mehr darüber wissen...", sourceObjective = "Bringt die Flamme von Orgrimmar zum Meister der Lehren.", progress = "Ihr glüht ja förmlich, {race}. Was habt Ihr da?", completion = "Was ist das? Sollte ich mich nicht täuschen, so wurde diese Flamme aus dem Herzen Orgrimmars entwendet! Die sengende Hitze spiegelt die kämpferischen Herzen der Orcs und Trolle wider. Was für ein Gewinn für unsere Sammlung! Wie mutig Ihr doch seid - sich in den Bau des Feindes einzuschleichen, um die heilige Flamme zu erlangen!\n\nIch frage mich, welch' Mächte sich in den anderen Städten versteckt halten...", sourceObjectiveStatus = "unverified-source-field" }
quests[9325] = { id = 9325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raubt die Flamme von Donnerfels", description = "Die Flamme, die dem Schamanen von Donnerfels entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Meister der Lehren könnte vielleicht mehr darüber wissen...", sourceObjective = "Bringt die Flamme von Donnerfels zum Meister der Lehren.", progress = "Ihr glüht ja förmlich, {race}. Was habt Ihr da?", completion = "Sollte mich meine Vermutung nicht täuschen, so wurde diese Flamme aus Donnerfels entwendet! Die Macht der Geister ist deutlich hörbar! Ihr seid ganz schön gerissen, {name}. Nehmt dies als gerechte Anerkennung Eures Könnens. Hm, hätten wir doch auch alle vier Flammen von den anderen Städten...", sourceObjectiveStatus = "unverified-source-field" }
quests[9326] = { id = 9326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raubt die Flamme von Unterstadt", description = "Die Flamme, die aus den Ruinen über Unterstadt entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Meister der Lehren könnte vielleicht mehr darüber wissen...", sourceObjective = "Bringt die Flamme von Unterstadt zum Meister der Lehren.", progress = "Ihr glüht ja förmlich, {race}. Was habt Ihr da?", completion = "Hm... was für ein seltsames Feuer! Es flackert schwach, ist fast nur noch ein Glühen, aber die Hitze ist stark. Ihr sagt, dass Ihr es aus Unterstadt entwendet habt? Faszinierend. Wer weiß, was wir mit den Flammen aller vier Städte erreichen könnten?", sourceObjectiveStatus = "unverified-source-field" }
quests[9327] = { id = 9327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verlassenen", description = "Ich weiß, es mag seltsam erscheinen, aber die Verlassenen sind hier, um uns zu helfen. Ihr solltet mit Hochexekutor Mavren sprechen. Er befindet sich in dem Turm im Westen der Stadt.\n\nWenn Ihr mit ihm gesprochen habt, kehrt bitte zu mir zurück, es gibt da eine schlimme Angelegenheit, bei der ich dringend Eure Unterstützung benötige.", sourceObjective = "Sprecht mit Hochexekutor Mavren in Tristessa in den Geisterlanden.", completion = "Ich weiß, wir Verlassenen mögen in Euren Augen monströs erscheinen, aber ich versichere Euch, wir sind für Euer Volk keine Bedrohung. Wir sind hier, weil wir einen gemeinsamen Feind haben: Dar'Khan den Verräter! Er ist zurückgekehrt und befehligt die Geißel von der Todesfestung im Süden aus.\n\nUnsere Anführerin, Lady Sylvanas Windläufer, stammt aus dieser Gegend, und war früher ein Elf. Sie hatte schon mit Dar'Khan zu tun und möchte ihn genauso gern tot sehen wie Eurer Volk.\n\nWir werden ihn zusammen besiegen, {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[9328] = { id = 9328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Held der Sin'dorei", description = "Dies ist der Beginn eines neuen Zeitalters für unser Volk, {name}. Wir werden unser Land zurückerobern und unseren Bund mit Sylvanas und ihren Verbündeten festigen.\n\nBringt den Kopf des Verräters nach Silbermond, zu Lor'themar Theron, dem Lordregenten Silbermond. Er wird begierig sein, die Neuigkeit zu erfahren.", sourceObjective = "Bringt Dar'Khans Kopf zu Lor'themar Theron in Silbermond.", progress = "Ihr wünscht eine Audienz bei mir, {class}? Ich kann mich nicht an eine Verabredung erinnern.", completion = "Nun, das ist ein Gesicht, das ich noch nicht so früh hier erwartet hätte.\n\nDas sind ziemlich gute Neuigkeiten, {name}, in mehr Hinsichten, wie Ihr Euch denken könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9329] = { id = 9329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verlassenen", description = "Ich weiß, es mag seltsam erscheinen, aber die Verlassenen sind hier, um uns zu helfen. Ihr solltet mit Hochexekutor Mavren sprechen. Er befindet sich in dem Turm im Westen der Stadt.\n\nWenn Ihr mit ihm gesprochen habt, kehrt bitte zu mir zurück, es gibt da eine schlimme Angelegenheit, bei der ich dringend Eure Unterstützung benötige.", sourceObjective = "Sprecht mit Hochexekutor Mavren in Tristessa in den Geisterlanden.", completion = "Die Verlassenen sind hier, weil wir und die Blutelfen einen gemeinsamen Feind haben: Dar'Khan! Er ist zurückgekehrt und befehligt die Geißel von der Todesfestung im Süden aus.\n\nLady Sylvanas Windläufer, die ursprünglich aus dieser Gegend hier stammt, hatte schon früher mit Dar'Khan zu tun und möchte ihn tot sehen!\n\nWir werden Ihn besiegen, {name}, und Ihr werdet uns dabei helfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[9330] = { id = 9330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raubt die Flamme von Sturmwind", description = "Die Flamme, die aus dem Zentrum von Sturmwind entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Geschichtenerzähler könnte vielleicht mehr darüber wissen...", sourceObjective = "Bringt die Flamme von Sturmwind zum Geschichtenerzähler.", progress = "Ihr glüht ja förmlich, {race}. Was habt Ihr da?", completion = "Also dieses hell leuchtende Feuer... Ihr sagt es kommt aus Stormwind? Bemerkenswert! Das muss ein ziemliches Abenteuer gewesen sein! Ich werde Euch dafür natürlich entlohnen. Solltet Ihr etwas Ähnliches finden, kommt bitte sofort zu mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[9331] = { id = 9331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raubt die Flamme von Eisenschmiede", description = "Die Flamme, die aus dem Zentrum von Eisenschmiede entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Geschichtenerzähler könnte vielleicht mehr darüber wissen...", sourceObjective = "Bringt die Flamme von Eisenschmiede zum Geschichtenerzähler.", progress = "Ihr glüht ja förmlich, {race}. Was habt Ihr da?", completion = "Diese kraftvolle Flamme muss aus den Hallen von Ironforge stammen; sie ist so unerschütterlich wie die Zwege selbst. Gute Beute, {name}. Hätte ich nur die Flammen der anderen Städte... naja, macht Euch nichts draus. Hier ist Euer Lohn.", sourceObjectiveStatus = "unverified-source-field" }
quests[9332] = { id = 9332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raubt die Flamme von Darnassus", description = "Die Flamme, die von der Küste Teldrassils entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Geschichtenerzähler könnte vielleicht mehr darüber wissen...", sourceObjective = "Bringt die Flamme von Darnassus zum Geschichtenerzähler.", progress = "Ihr glüht ja förmlich, {race}. Was habt Ihr da?", completion = "Dieses Feuer ist mit uraltem Kummer erfüllt, {name}. Ihr habt es aus dem Herzen Teldrassils, ja? Unglaublich! Hier, als Anerkennung für Euer Können. Kehrt zu mir zurück, falls Ihr etwas Ähnliches finden solltet - ich könnte Verwendung dafür haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[9333] = { id = 9333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handschuhe der Argentumdämmerung", progress = "Bringt Ihr mir dreißig nekrotische Runen, gebe ich Euch im Gegenzug einen Handschutz Eurer Wahl dafür. Dieser sollte sich in Eurem Kampf gegen die untote Geißel als sehr nützlich erweisen.", completion = "Ihr habt gute Arbeit geleistet, {name}. Nehmt den von Euch gewählten Handschutz als Dank für Eure Mühen." }
quests[9334] = { id = 9334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesegnetes Zauberöl", progress = "Die Argentumdämmerung wird Euch im Tausch gegen die nekrotischen Runen der Geißelinvasoren eine Phiole gesegnetes Zauberöl geben.", completion = "Ich hoffe, dass Ihr in Euren zukünftigen Schlachten davon Gebrauch machen könnt." }
quests[9335] = { id = 9335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geweihte Wetzsteine", progress = "Wenn Ihr mir acht nekrotische Runen von den Geißelinvasoren besorgt, kann ich Euch einen geweihten Wetzstein dafür geben. Er sollte Euch im Kampf gegen die Diener des Lichkönigs eine große Hilfe sein.", completion = "Danke, {name}. Hier ist Euer geweihter Wetzstein. Verwendet ihn weise." }
quests[9336] = { id = 9336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erstklassiger Heiltrank" }
quests[9337] = { id = 9337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erstklassiger Manatrank", progress = "Neben unseren anderen Vorräten verfügen wir auch über eine gewisse Zahl an erheblichen Manatränken, die für Euch von Nutzen sein könnten. Ich werde Euch einen im Tausch gegen fünfzehn nekrotische Runen geben.", completion = "Bitte sehr, {name}. Seid vorsichtig da draußen. Wir sind zu wenige, als dass wir uns viele Verluste auf dem Schlachtfeld leisten könnten." }
quests[9338] = { id = 9338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treue zum Zirkel des Cenarius", progress = "Selbst wenn Ihr keinen Bedarf an unseren materiellen Belohungen habt, sind diese Abzeichen ein Symbol für gegenseitiges Vertrauen und Freundschaft.\n\nBringt sie mir. Außerordentliche Dienste von Euch werde ich sorgsam vermerken.", completion = "Ihr ehrt uns, {name}. Eure fortgesetzten Anstrengungen helfen uns, alle Hindernisse zu überwinden." }
quests[9339] = { id = 9339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Lohn des Diebes", description = "Die Flamme, die aus dem unmittelbaren Zentrum von Sturmwind entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber (NAME) könnte vielleicht mehr darüber wissen...", completion = "Ihr habt Euch heute bewiesen, {name}.\n\nIch habe zwar nicht viel, das ich Euch geben könnte, aber bitte nehmt diese Krone, eine passende Belohnung für einen Eroberer. Möge sie Euren Weg erleuchten." }
quests[9340] = { id = 9340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die große Kluft", description = "Wir stehen kurz davor, vollständig von den Streitkräften der Allianz eingekesselt zu werden. Mit dem ständigen Zustrom von Sin'doreiflüchtlingen aus Azeroth, müssen wir einen Weg finden, der vor den neugierigen Blicken des Feindes sicher ist.\n\nIch habe darüber etwas nachgedacht und bin kürzlich zu einer Lösung gekommen. Wir werden eine sichere Passage durch die große Kluft etablieren.\n\nJa, auch wenn es dort nur so von tödlichen Felsklauen wimmelt, sind sie doch nichts weiter als bloße Tiere, denen wir beibringen können, uns zu fürchten. Ich möchte, dass Ihr loszieht und eine größere Anzahl dieser Biester erlegt. Zeigen wir ihnen, was Angst ist!", sourceObjective = "Waldläuferhauptmann Venn'ren in der Falkenwacht möchte, dass Ihr 8 Steinsichelwelpen und 3 Steinsichelalphas bei der großen Kluft östlich der Falkenwacht erlegt.", completion = "Gute Arbeit, {name}. Das sollte die Felsklauen lehren, sich von uns fernzuhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[9341] = { id = 9341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wappenrock der Argentumdämmerung", progress = "Ihr habt unserer Sache sehr gedient, {name}. Wenn ihr wollt, kann ich Euch einen Wappenrock der Argentumdämmerung zur Verfügung stellen. Wir sind stolz, Euch zu unseren Verbündeten zu zählen.", completion = "Nehmt diesen Wappenrock und tragt ihn mit Stolz. Vielleicht regen Eure Taten auch andere dazu an, zu den Waffen zu greifen und an unserem Kampf gegen die Geißel teilzunehmen." }
quests[9342] = { id = 9342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plündernde Krustenbohrer", description = "Als ob es nicht schon schlimm genug wäre, dass die Gan'arg in den Minen eingefallen sind, rücken uns nun diese Riesenwürmer von der anderen Seite auf die Pelle!\n\nDa Thrallmars Garnison mit der Verteidigung gegen die Legion und dem Pflegen der Verwundeten beschäftigt ist, bedeutet das, dass ich und die Minenarbeiter uns um dieses Problem kümmern müssen.\n\n<Der Großknecht zeigt auf die schlafenden Peons.>\n\nUnd Ihr sehr ja selbst wie hilfreich sie sind...\n\nIch bezahle Euch gerne ihr Gehalt, wenn Ihr ein paar dieser Würmer vernichtet.", sourceObjective = "Großknecht Razelcraz bei den Minen in der Nähe von Thrallmar möchte, dass Ihr 15 plündernde Krustenbohrer tötet. Die Würmer haben die Angewohnheit, unplötzlich aus ihren unterirdischen Tunneln anzugreifen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9343] = { id = 9343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wappenrock der Argentumdämmerung", progress = "Ihr habt unserer Sache sehr gedient, {name}. Wenn ihr wollt, kann ich Euch einen Wappenrock der Argentumdämmerung zur Verfügung stellen. Wir sind stolz, Euch zu unseren Verbündeten zu zählen.", completion = "Nehmt diesen Wappenrock und tragt ihn mit Stolz. Vielleicht regen Eure Taten auch andere dazu an, zu den Waffen zu greifen und an unserem Kampf gegen die Geißel teilzunehmen." }
quests[9344] = { id = 9344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der überstürzte Aufbruch", description = "Seid gegrüßt, {name}. Die Scherbenwelt ist ein Ort voller Gefahren, beinahe jedes Mitglied unserer Expedition musste diese leidvolle Erfahrung machen. Ich befürchte, der junge Grelag hat diese Lektion aus erster Hand erfahren.\n\nEr ist ein viel versprechender Schüler, doch es mangelt ihm an Geduld! Er studiert mit Begeisterung die Geschichte seines Volkes und vergisst dabei manchmal die Gefahren des heutigen Lebens.\n\nEr ist zum Rückenbrecherposten aufgebrochen, ohne an die Legion und die Höllenorcs zu denken. Ich habe Angst, dass ihm etwas zugestoßen ist.", sourceObjective = "Scharfseherin Regulkut möchte, dass Ihr ihren Schüler Grelag findet.", sourceObjectiveStatus = "unverified-source-field" }
quests[9345] = { id = 9345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herstellung der Salbe", description = "Als ich gerade Zeth'Gor erkennen konnte, wurde ich von einer Patrouille der Legion entdeckt. Ich rannte los in der Hoffnung, dass ich mich in einem der Türme in der Ferne verstecken kann, aber einer ihrer Teufelshunde hat mich eingeholt und mich fast zerfleischt!\n\nIch konnte entkommen, aber mein Bein ist in einem sehr schlechten Zustand. Steingardist Ambelan hat mich gefunden und hierher gebracht.\nJetzt muss ich einen Weg finden, um mein Bein zu versorgen. Wirbelkraut wächst in und um das Tal der Knochen im Norden herum. Eine Salbe daraus wird den Schmerz lange genug betäuben, dass ich weiterreisen kann.", sourceObjective = "Grelag im Rückenbrecherposten möchte, dass Ihr ihm 12 Höllenwirbelkräuter für seine Salbe bringt.", progress = "Habt Ihr die Pflanzen gefunden?", completion = "Die sollten Ihren Zweck erfüllen. Ich werde die Salbe fertigstellen und mein Bein schienen, bevor ich nach Thrallmar aufbreche. Wieso glaube ich genau zu wissen, was mir Scharfseherin Regulkut erzählen wird, wenn sie mich so sieht?\n\n<Grelag seufzt halbherzig.>\n\nVielen Dank für Eure Hilfe, {name}. Ich habe noch einige von den Höllenwirbelkräutern übrig. Nehmt sie mit, wenn Ihr sie braucht. Wer weiß, wofür sie noch gut sind?", sourceObjectiveStatus = "unverified-source-field" }
quests[9346] = { id = 9346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn Hölleneber fliegen", description = "Habt Ihr schon mal einen fliegenden Hölleneber gesehen? Die brauchen nicht mal Flügel!\n\n<Wachtkommandant Krunk lacht schallend.>\n\nDer Kampf gegen die Lager der Legion im Norden hat unsere Vorräte restlos erschöpft, einschließlich der Katapultmunition. Also der perfekte Augenblick, mal etwas völlig Neues auszuprobieren.\n\nStatt Steine zu verschießen, dachte ich daran, die Kadaver verhungernder Hölleneber in Brand zu stecken, um damit die Lager der Legion zu bombardieren.\n\nMeldet Ihr Euch freiwillig oder muss ich Euch erst dazu zwingen?", sourceObjective = "Wachtkommandant Krunk in Thrallmar möchte, dass Ihr ihm 10 klobige Hölleneberkadaver von verhungernden Höllenebern bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9347] = { id = 9347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wilde Leerwandler", description = "Als Ihr die Essenz eingehender betrachtet, erblickt Ihr bösartig umherwirbelnde Energien, die in einem Gefäß aus einem unbekannten Material eingeschlossen sind. Ihr haltet einen Moment inne und fühlt, wie sich irgendetwas in Eure Gedanken schleicht und Ihr verspürt das Verlangen, näher zu kommen und tiefer in die Essenz zu blicken.\n\nAls Ihr bemerkt, dass Euer Bewusstsein immer mehr abgleitet, wendet Ihr erschrocken Euren Blick ab. Während Ihr überlegt, was Ihr mit Eurem Fund anstellen sollt, bemerkt Ihr am Rande Eures Bewusstseins noch immer die lauernde Gegenwart der Essenz.", sourceObjective = "Bringt die pulsierende Leerwandleressenz zu Mahuram Starkhuf in Thrallmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[9348] = { id = 9348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felshetzerzusammentrieb", description = "Die Scherbenwelt ist voller faszinierender Lebewesen. Faszinierend und extrem tödlich.\n\nDas Land beherbergt eine große Zahl der unterschiedlichsten Raubtiere. Das erscheint zunächst seltsam für solch ein ödes Land, doch bei genauer Betrachtung haben diese Kreaturen untereinander eine Art Hierarchie entwickelt.\n\nDie Felsklauen haben sich eine weitere tödliche Bestie untertan gemacht, den Felshetzer. Anscheinend züchten und halten sie diese als Jagd- und Wachtiere. Ich muss unbedingt in Erfahrung bringen, mit welchen Methoden sie die Felshetzer abrichten. Dazu müssen wir ihre Brutstätte nahe Terokkar im Südwesten ausräuchern und untersuchen.", sourceObjective = "Tötet 10 gefangene Felshetzerjungtiere und sammelt 12 Felshetzereier für Mahuram Starkhuf in Thrallmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[9349] = { id = 9349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felshetzereier sammeln", description = "Ich bin am verhungern!\n\nIst das nicht ironisch? Ein verhungernder Koch?\n\n<Legassi lacht halbherzig und tippt auf ein gefaltetes Pergament in seiner Tasche.>\n\nLaut dieser Touristenkarte, der wir gefolgt waren, bevor wir so hinterhältig niedergeschossen wurden, gibt es im Südwesten eine Gegend, nahe bei den Wäldern von Terokkar. Sie wird der Messerdornpfad genannt und angeblich soll es dort von leckeren Felshetzereiern nur so wimmeln!\n\nIch könnte ein tolles Festmahl daraus zaubern, wenn nur jemand mutig genug wäre, dorthin zu gehen und ein paar zu sammeln!", sourceObjective = "Bringt 12 Felshetzereier zu Legassi bei der Zeppelinabsturzstelle auf der Höllenfeuerhalbinsel.", progress = "Habt Ihr die Eier schon?\n\n<Legassis Magen knurrt vor Vorfreude.>", completion = "Für ausgezeichnete Küche braucht man ausgezeichnete Zutaten. Und diese Eier sehen großartig aus!\n\nIch habe gerade meine Pfanne geputzt, Ihr seid also herzlich eingeladen, mir bei einem Mahl Gesellschaft zu leisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[9351] = { id = 9351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wilde Leerwandler", description = "Auch wenn ich den Rahmen des Zeppelins repariert bekomme, muss ich einen Ersatztreibstoff finden! Ich habe kein Benzin mehr, und es gibt weit und breit keine Tankstelle!\n\nSüdlich von hier liegt eine Gegend namens Sphärenfelder. Dort wimmelt es nur so von wilden und unkontrollierten Leerwandlern, aber für mich sind sie eher wandelnde Batterien.\n\nWenn Ihr mir genug von Ihrer Essenz bringt, kann ich damit den Motor des Zeppelins zum Laufen bekommen. Ich wette fünf Gold, dass ich dann sogar einen niedrigeren Verbrauch habe!", sourceObjective = "Bringt 10 kondensierte Leerwandleressenzen zu \"Schreihals\" Quack Lufthans bei der Zeppelinabsturzstelle.", progress = "Konntet Ihr die Essenzen besorgen?", completion = "Perfekt! Ich glaube sogar, dass das so gut funktionieren wird, dass ich den Motor umbauen muss, damit ich alle Vorteile dieses Kraftstoffs nutzen kann! Falls - ich meine natürlich - wenn wir hier wegkommen, muss ich allen in Area 52 meine Entwürfe zeigen!", sourceObjectiveStatus = "unverified-source-field" }
quests[9352] = { id = 9352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darnassische Eindringlinge", description = "Abgesehen von der konstanten Bedrohung durch die Getriebenen, befasse ich mich auch mit den zahlreichen Berichten über angebliche Nachtelfensichtungen.\n\nObwohl viele dieser Sichtungen frei erfunden sind, gibt es doch einen Vorfall, der weiterer Untersuchungen bedarf. Das Sanktum des Westens, eine unserer primären Energiequellen, hatte eine massive Fehlfunktion und Gerüchte, eine darnassische Sabotageaktion sei der Grund dafür, machen die Runde.\n\nBegebt Euch dorthin und kümmert Euch um jeden, der verdächtig aussieht. Meldet Euch bei Leybewahrerin Velania, sie überwacht das Sanktum.", sourceObjective = "Reist zum Sanktum des Westens südwestlich vom Falkenplatz und vernichtet jegliche Eindringlinge, die Ihr dort findet. Berichtet anschließend Leybewahrerin Velania.", completion = "Nachtelfen? Hier? Diese Ratten!\n\nGlaubt Ihr, es besteht irgendeine Verbindung zu der Fehlfunktion in meinem Sanktum? Falls Ihr irgendwelche Informationen habt, bringt Ihr sie besser umgehend zu Hauptmann Sonnenmal!", sourceObjectiveStatus = "unverified-source-field" }
quests[9353] = { id = 9353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "iCoke-Geschenkgutschein einlösen" }
quests[9355] = { id = 9355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Aufgabe für einen intelligenten Helden", description = "Gut, {class}. Nun, da die Verstärkung anrückt, können wir endlich wieder ein mehr oder weniger normales Leben führen.\n\nEines unserer ersten Ziele ist die Wiederaufnahme des Transports von Männern und Waren auf der Straße nach Südwesten, aber dazu müssen wir sie erst von den Krustenbohrern zurückfordern, die diese Gegend in Beschlag genommen haben.\n\nWenn Ihr uns bei dieser Aufgabe helfen würdet, wären die Söhne Euch sehr dankbar. Gebt auf die aufgewühlte Erde Acht, die sie hinterlassen!", sourceObjective = "Tötet 15 plündernde Krustenbohrer und kehrt dann zu Großknecht Biggums in der Ehrenfeste zurück.", completion = "Gut gemacht, {name}. Wir sollten uns aber nicht zu früh freuen. Ich bin mir sicher, dass wir diese Würmer nicht zum letzten Mal gesehen haben. Wenn sie ihre hässlichen Köpfe wieder in diese Gegend strecken sollten, werden die Söhne sie schon erwarten!", sourceObjectiveStatus = "unverified-source-field" }
quests[9356] = { id = 9356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So weich wie Butter", description = "Quack sagt immer, er fliegt \"so weich wie Butter\". Ich glaube eher, sein Kopf ist so weich wie Butter!\n\nSchaut Euch nur die Trümmer da drüben an. Er nennt das eine harte Landung.\n\nKlar, wir wurden beschossen, und ich würde es ihm ja auch nachsehen, wenn er nicht immer so mit seinen Flugkünsten angeben würde!\n\nIch glaube, ich koche ihm ein paar Flügel, um ihm einmal einen Wink mit dem Zaunpfahl zu geben. Im Osten, im Tal der Knochen, findet Ihr Knochenhäuterbussarde. Ihre Flügel sind fleischig, dick und perfekt für meine Zwecke.", sourceObjective = "Bringt 12 fleischige Bussardflügel zu Legassi bei der Zeppelinabsturzstelle.", progress = "Ich kann es kaum erwarten, seinen Gesichtsausdruck zu sehen, wenn er reinhaut! Seit dem Absturz beschwert er sich, dass ich nur ans Essen denke. Nun, jemand muss uns schließlich ernähren, während er am Zeppelin herumschraubt!", completion = "Felshetzereier... Bämm!\n\nHölleneberspeck... Bämm!\n\nBussardflügel... Bämm! Bämm!\n\nWas für ein großartiges Essen. Ihr solltet wirklich mal probieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[9357] = { id = 9357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldet Euch bei Aeldon Sonnenmal", description = "Wenn Ihr nach Arbeit sucht, dann sprecht mit Hauptmann Sonnenmal beim inneren Elfentor, geht einfach durch die Türen hinter mir.\n\nLasst mich jetzt in Ruhe, ich muss diesen Halunken verhören.", sourceObjective = "Meldet Euch bei Aeldon Sonnenmal beim inneren Elfentor im Immersangwald.", sourceObjectiveStatus = "unverified-source-field" }
quests[9358] = { id = 9358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waldläuferin Sareyn", description = "Betrachtet die Sicherheit dieses Orts nicht als selbstverständlich. Wir werden von der Geißel im Osten und von den Getriebenen im Westen belagert.\n\nWaldläuferin Sareyn sichert unsere Grenzen vor den Untoten, die uns von der Todesschneise her bedrängen. Folgt der Straße in Richtung Osten und erkundigt Euch, ob sie Unterstützung braucht.", sourceObjective = "Meldet Euch bei Waldläuferin Sareyn außerhalb von Morgenluft im Immersangwald.", completion = "Ihr seid hier, um zu helfen? Warum habt Ihr das nicht gleich gesagt? Wir können jede helfende Hand gebrauchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[9359] = { id = 9359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuflucht der Weltenwanderer", description = "Ihr habt uns geholfen die Getriebenen wieder unter Kontrolle zu bekommen und dies war von unschätzbarem Wert. Die Weltenwanderer könnten jemanden wie Euch in ihrem Kampf gegen die Amanitrolle gebrauchen.\n\nHaltet nach der Zuflucht der Weltenwanderer nordöstlich von hier Ausschau, sprecht mit Leutnant Dämmerflucht und erkundigt Euch, ob sie Unterstützung braucht.", sourceObjective = "Meldet Euch bei Leutnant Dämmerflucht bei der Zuflucht der Weltenwanderer im Immersangwald.", completion = "Ihr seid hier, um zu helfen? Ausgezeichnet!\n\nDer Kampf gegen die Amanitrolle hat uns sehr in Anspruch genommen und fähige Kämpfer wie Ihr sind stets willkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9360] = { id = 9360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff der Amani", description = "Ihr versteht zwar die Sprache dieser Schlachtpläne nicht, aber Ihr könnt klar eine Karte mit den eingetragenen Positionen der Zuflucht der Weltenwanderer und von Morgenluft ausmachen.\n\nAm besten informiert Ihr Leutnant Dämmerflucht bei der Zuflucht der Weltenwanderer darüber.", sourceObjective = "Bringt die Invasionspläne der Amani zu Leutnant Dämmerflucht bei der Zuflucht der Weltenwanderer.", progress = "Was wollt Ihr mir zeigen?", completion = "Die Trolle haben uns hier festgehalten, während sie einen Angriff auf Morgenluft planten. Wir hatten nichts dergleichen erwartet.", sourceObjectiveStatus = "unverified-source-field" }
quests[9361] = { id = 9361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hölleneber, die etwas andere Delikatesse", description = "Diese Eier sind wundervoll, aber was haltet Ihr davon, wenn wir noch einen Zahn zulegen?\n\nEine Scheibe Speck würde unser Mahl erst richtig abrunden, und ich weiß ganz genau, wo man sie herbekommen könnte.\n\nDieser Ort wimmelt nur so von Höllenebern. Natürlich kann hier niemand das Fleisch überprüfen und weichklopfen, aber wir haben Glück!\n\n<Legassi kramt in seinem Beutel und holt eine Flasche hervor.>\n\nDies wurde zwar nicht gemacht, um es mit Schweinefleisch zu benutzen, aber Improvisation ist alles!", sourceObjective = "Legassi bei der Zeppelinabsturzstelle möchte, dass Ihr 8 Stück geläutertes Hölleneberfleisch sammelt. Um das Fleisch zu reinigen, schüttet die Läuterungsmischung über das besudelte Hölleneberfleisch, das Ihr von den Höllenebern gesammelt habt.", progress = "Habt Ihr das Hölleneberfleisch erfolgreich geläutert?", completion = "Hmmm...\n\nEs sieht essbar aus, wenn man es richtig würzt. Erzählt Quack aber nicht, woraus sein Frühstück besteht, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[9362] = { id = 9362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsherr Krellian", description = "Die Zeit drängt, {name}! Meine Orakelsprüche haben eine machtvolle Quelle der Magie offenbart. Ich kann den Turm nicht verlassen und bitte Euch deshalb, diese bösartige Kreatur, die im Besitz dieses Artefakts ist, zu töten.\n\nDer erbärmliche Schwachkopf ist bekannt als Kriegsherr Krellian und versteckt sich hinter seinen Wachen im Tempel von Zin-Malor. Verbrennt ihn zu Asche und nehmt die prismatische Muschel, die er so begehrt, an Euch.", sourceObjective = "Beschafft die prismatische Muschel für Erzmagier Xylem. Der Erzmagier befindet sich in einem Turm auf den Klippen von Azshara.", progress = "Es ist keine Zeit zu verlieren! Habt Ihr die Muschel?", completion = "Mh, diese Muschel wird wahrlich von einer seltsamen Aura umgeben. Es scheint geradezu angebracht, dass Eure Belohnung für die Wiederbeschaffung zum Teil daraus besteht, diese magischen Fähigkeiten zu testen...", sourceObjectiveStatus = "unverified-source-field" }
quests[9363] = { id = 9363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warnt Morgenluft", description = "Geht nach Morgenluft und klärt Waldläufer Degolien über die Pläne der Amani auf. Morgenluft muss sich auch nach dem Tod von Zul'marosh noch auf einen Angriff der Trolle vorbereiten. Sagt Degolien, dass ich ihm so schnell wie möglich Verstärkung schicken werde.", sourceObjective = "Reist nach Morgenluft im Immersangwald und sprecht mit Waldläufer Degolien.", completion = "Die Informationen, die Ihr mir gebracht habt, sind von entscheidender Bedeutung, {name}. Jetzt, da wir über die Pläne der Trolle Bescheid wissen, können wir uns auf einen Angriff vorbereiten.\n\nSie werden uns nicht ahnungslos überrumpeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[9364] = { id = 9364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gespaltene Magie", description = "Meine Untersuchungen haben den einzigartigen Zweck für die prismatische Muschel enthüllt.\n\nGreift die Grollflossen von Azshara mit Verwandlungszaubern an und tragt dabei diese Muschel bei Euch. Wenn Ihr einen Moment wartet, wird die chaotische Aura der Muschel dafür sorgen, dass sie sich für eine kurze Zeit in mehrere kleinere Versionen aufspalten. Tötet diese Kopien so schnell wie möglich, und deren gespaltene Essenzen werden in der Muschel gesammelt.\n\nKehrt zu mir zurück, sobald die Muschel gefüllt ist.", sourceObjective = "Verwandelt die Grollflossen von Azshara und tötet die Kopien, die einige Sekunden später auftauchen. Wenn Ihr 50 verwandelte Kopien vernichtet habt, kehrt zu Erzmagier Xylem in Azshara zurück.", progress = "Habt Ihr die Magie eingesammelt?", completion = "Wunderbar! Prächtig!\n\nNun sind wir in der Lage, diese Magie zu einem neuen Zauber zu formen. Seht!", sourceObjectiveStatus = "unverified-source-field" }
quests[9365] = { id = 9365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Lohn des Diebes", description = "Die Flamme, die aus dem unmittelbaren Zentrum von Sturmwind entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber (NAME) könnte vielleicht mehr darüber wissen...", completion = "Ihr habt Euch heute bewiesen, {name}.\n\nIch habe zwar nicht viel, das ich Euch geben könnte, aber bitte nehmt diese Krone, eine passende Belohnung für einen Eroberer. Möge sie Euren Weg erleuchten." }
quests[9366] = { id = 9366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach Teufelsblut", description = "Nordöstlich von hier liegen die Teiche von Aggonar. Vor langer Zeit waren sie ein Heiligtum der Draenei, doch fielen sie der Verderbnis anheim, als das Blut des Dämonen Aggonar in die heiligen Wasser vergossen wurde.\n\nObwohl es alt und verwässert ist, ist das Blut noch immer von einer enormen Macht erfüllt. Angetrieben durch die puren dämonischen Energien des ursprünglichen Blutes, durchstreifen Terrorbestien dieses Gebiet. Vernichtet sie und sammelt so viel von dem Teufelsblut ein, wie Ihr tragen könnt. Ich werde Euch fürstlich belohnen.", sourceObjective = "Ryathen der Düstere an der Falkenwacht auf der Höllenfeuerhalbinsel möchte, dass Ihr ihm 6 Teufelsblutproben von den Terrorbestien bringt, die bei den Teichen von Aggonar umherstreifen.", progress = "Das Teufelsblut... habt Ihr es bekommen, {name}?", completion = "Die in den Proben gespeicherten Energien sind unfassbar stark, {name}. Nun müssen wir nur noch sicherstellen, dass wir auch in Zukunft freien Zugriff auf das Teufelsblut haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[9367] = { id = 9367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Fest des Feuers", description = "Die Zeit des Sonnenwendfests ist wieder angebrochen!\n\nJedes Jahr werden, wie die Tradition es verlangt, Flammenbewahrer auserkoren, die die Freudenfeuer in unseren Hauptstädten hüten. Auch wenn Feuer in ganz Azeroth brennen, so müssen unsere stets die heißesten und hellsten von allen sein, um dieser Zeit im Jahr ausreichend Ehrerbietung zu erweisen.\n\nIch hätte da übrigens eine Aufgabe für Euch. Mir ist noch nicht zu Ohren gekommen, ob die Feuer in allen Hauptstädten auch wirklich ordentlich brennen. Reist selbst dorthin und wärmt Euch im Schein der Flammen - überzeugt Euch, dass sie ausreichend heiß sind!", sourceObjective = "Wärmt Euch an den Freudenfeuern in Sturmwind, Eisenschmiede und Darnassus. Sprecht anschließend mit einem Meister der Lehren innerhalb der Hauptstädte.", completion = "Ausgezeichnet! Scheinbar haben wir dieses Jahr pflichtgetreue Flammenbewahrer ernannt, wenn die Freudenfeuer so herrlich brennen, wie Ihr es berichtet. Danke, dass Ihr der Sache für mich nachgegangen seid. Hier, nehmt dies als kleines Zeichen für meine Wertschätzung.", sourceObjectiveStatus = "unverified-source-field" }
quests[9368] = { id = 9368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Fest des Feuers", description = "Die Zeit des Sonnenwendfests ist wieder angebrochen!\n\nJedes Jahr werden, wie die Tradition es verlangt, Flammenbewahrer auserkoren, die die Freudenfeuer in unseren Hauptstädten hüten. Auch wenn Feuer in ganz Azeroth brennen, so müssen unsere stets die heißesten und hellsten von allen sein, um dieser Zeit im Jahr ausreichend Ehrerbietung zu erweisen.\n\nIch hätte da übrigens eine Aufgabe für Euch. Mir ist noch nicht zu Ohren gekommen, ob die Feuer in allen Hauptstädten auch wirklich ordentlich brennen. Reist selbst dorthin und wärmt Euch im Schein der Flammen - überzeugt Euch, dass sie ausreichend heiß sind!", sourceObjective = "Wärmt Euch an den Freudenfeuern in Orgrimmar, Donnerfels und Unterstadt. Sprecht anschließend mit einem Geschichtenerzähler innerhalb der Hauptstädte.", progress = "Brennen alle Feuer?", completion = "Ausgezeichnet! Scheinbar haben wir dieses Jahr pflichtgetreue Flammenbewahrer ernannt, wenn die Freudenfeuer so herrlich brennen, wie Ihr es berichtet. Danke, dass Ihr der Sache für mich nachgegangen seid. Hier, nehmt dies als kleines Zeichen für meine Wertschätzung.", sourceObjectiveStatus = "unverified-source-field" }
quests[9369] = { id = 9369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederaufladen der Heilkristalle", description = "Wir sind die Draenei. Unser Schiff ist hier abgestürzt und es gibt etliche Verwundete. Unsere dringlichste Sorge ist die Erschöpfung unserer Heilkristalle. Wir müssen sie so schnell wie möglich wieder aufladen!\n\nUnglücklicherweise können wir das derzeit nur, indem wir das Blut der einheimischen Talmotten abzapfen. Ihr Blut eignet sich als Ersatzstoff.\n\nMan findet die Motten entlang des gesamten Tals, jedoch verstärkt im Nordwesten.", sourceObjective = "Beschafft Euch 8 Phiolen mit Mottenblut von den in der Nähe hausenden Talmotten und bringt sie zu Proenitus bei der Absturzstelle im Am'mental.", progress = "Habt Ihr schon das benötigte Mottenblut für die Heilkristalle? Überlebende sind über das gesamte Tal verstreut und die Zeit drängt!", completion = "Wie bedauernswert, dass diese Kreaturen sterben mussten, damit wir überleben können - wahlloses Töten entspricht nicht dem Weg der Draenei. Wie auch immer, das von Euch gesammelte Blut wird unsere Heilkristalle wieder aufladen, somit war ihr Opfer nicht umsonst.", sourceObjectiveStatus = "unverified-source-field" }
quests[9370] = { id = 9370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stoppt das Säuberungsritual", description = "Unsere Späher haben kürzlich einen Paladin der Draenei in der Nähe der Teiche von Aggonar aufgegriffen. Wir nehmen an, dass er vorhatte, an einem Säuberungsritual zur Reinigung der Teiche teilzunehmen. Natürlich müssen wir das Vorhaben der Draenei stoppen, oder unsere Teufelsblutquelle wird für immer versiegen.\n\nEr hatte diesen Signalstein bei sich. Offensichtlich hatte er den Auftrag, einen sicheren Ort zu markieren, an dem ein Priester - sie selbst nennen sich 'Anachoret' - in aller Sicherheit ein Säuberungsritual durchführen kann. Nehmt den Stein und platziert ihn am Altar von Aggonar und bereitet einen Hinterhalt für die eintreffenden Draenei vor.\n\nIch schlage vor, dass Ihr besser ein oder zwei Freunde mit Euch bringt.", sourceObjective = "Platziert den Signalstein bei den Teichen von Aggonar am Altar von Aggonar und besiegt alle Anachoreten der Draenei, die auf Eure Signal reagieren. Kehrt anschließend mit dem Signalstein zu Ryathen dem Düsteren bei der Falkenwacht zurück.", progress = "Ihr seid zurückgekehrt, {name}. Habt Ihr dem Aberwitz der Draenei ein Ende gesetzt?", completion = "Das wird diese heiligen Fanatiker lehren, sich um ihren eigenen Kram zu kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[9371] = { id = 9371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Botanikerin Taerix", description = "{name}, Botanikerin Taerix braucht Eure Hilfe. Bitte, sucht sie bei ihren Lehrlingen außerhalb der Westseite des Schiffes auf.", sourceObjective = "Sprecht mit Botanikerin Taerix bei der Absturzstelle im Am'mental.", completion = "Oh, welch Glück, dass Ihr hier seid! Wir haben Einiges zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[9372] = { id = 9372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonische Verderbnis", description = "Willkommen im Posten des Cenarius, {class}. Wir bekommen hier draußen nicht oft Besuch, daher freue ich mich ganz besonders über Eure Anwesenheit. Meine Arbeit mit den Lebewesen dieser trostlosen Umgebung macht es oft erforderlich, alleine in die abgelegensten Winkel zu reisen.\n\nDie Expedition des Cenarius hat mich mit dem Studium einiger der gefährlichsten Tiere der Scherbenwelt beauftragt, und dabei habe ich eine verblüffende Entdeckung gemacht. Obwohl viele Kreaturen bereits massive Veränderungen durchgemacht haben, scheint die Verderbnis noch immer neue Mutationen hervorzurufen. Ich habe mit dem Sammeln von Blutproben begonnen, um diese Veränderungen zu dokumentieren, und dabei ist mir jede Hilfe recht.", sourceObjective = "Thiah Rotmähne im Posten des Cenarius auf der Höllenfeuerhalbinsel möchte, dass Ihr 6 Blutproben eines Höllenebers von bulligen Höllenebern sammelt.", progress = "Habt Ihr die Blutproben bekommen?", completion = "Gute Arbeit, {name}. Diese Blutproben werden mir bei meinen Forschungen, und der Expedition bei ihren Studien der Scherbenwelt und ihrer Lebewesen, sehr dienlich sein.\n\nWenn ich den Grund für die fortschreitende Veränderung der Tiere herausfinden könnte, könnte ich vielleicht ein Gegengift herstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9373] = { id = 9373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fehlender Schriftverkehr", description = "Bei der Untersuchung des ramponierten Lederkoffers stellt Ihr fest, dass die Beschädigung des Behälters von der ätzenden Flüssigkeit im Verdauungstrakt des Wurms herrühren muss. Das Leder scheint einst kunstvoll verarbeitet gewesen zu sein, aber die Verzierungen sind nicht mehr deutlich sichtbar.\n\nDas Einzige, was noch zu erkennen ist, ist ein abgenutztes Symbol des Zirkels des Cenarius. Da Ihr nichts über den Inhalt wisst, haltet Ihr es für das Beste, den Koffer zu einem Mitglied des Zirkels zu bringen.", sourceObjective = "Bringt den zerfressenen Lederkoffer zu Thiah Rotmähne in der Nähe der Ruinen von Sha'naar im westlichen Teil der Höllenfeuerhalbinsel.", progress = "Guten Tag, {class}. Was bringt Euch in mein Lager?", completion = "Danke, dass Ihr mir dies hier gebracht habt, {class}. Ich habe mich schon gewundert, warum ich so lange nichts mehr von der Expedition gehört habe. Ich frage mich, wie lange diese Nachricht schon unterwegs ist und was wohl aus ihrem Überbringer geworden ist.\n\nHier habt Ihr etwas Geld für Eure Mühen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9374] = { id = 9374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arelions Tagebuch", description = "Mein Mann Arelion war seit unserer Ankunft in der Scherbenwelt von den Teichen von Aggonar fasziniert. Er verbrachte fast seine gesamte Zeit mit dem Studium der heimischen Schleimarten!\n\nVor einigen Tagen verschwand er spurlos. Man sagte mir, dass er tot sei und dass ich nichts mehr für ihn tun könnte.\n\nDoch was ich noch zu tun vermag, ist sicherzustellen, dass seine Forschungen nicht mit ihm gestorben sind. Begebt Euch zu den Teichen im Nordosten und haltet nach den Seiten seines Tagebuchs Ausschau. Er bewahrte sie immer in einem braunen Wanderknappsack auf.", sourceObjective = "Magistrix Carinda bei der Falkenwacht auf der Höllenfeuerhalbinsel möchte, dass Ihr zu den Teichen von Aggonar reist und Arelions Tagebuch sucht.", progress = "Hattet Ihr Glück, {name}? Die Teiche von Aggonar liegen nördlich der Höllenfeuerzitadelle.", completion = "Das Tagebuch meines Ehemanns... hat nicht das Geringste mit seinen Forschungen zu tun!\n\nWie konnte ich nur so blind sein? \"Die magischen Eigenschaften dämonisch beeinflusster Schleimformen\", beinahe hätte ich es geglaubt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9375] = { id = 9375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg zur Falkenwacht", description = "<Auf dem geschundenen Gesicht des Blutelfen zeichnet sich bei Eurem Anblick Erleichterung ab.>\n\nBitte, {class}, holt mich aus diesem Käfig heraus! Ich bin der Gruppe aus Thrallmar, trotz Martik Tor'seldoris Warnungen, vorausgereist.\n\nSchreckliche Kreaturen lauerten mir auf. Ich glaube, es waren diese Felshetzer, von denen er immer sprach. Zunächst gelang es mir ihnen zu entkommen, doch das war erst der Anfang meiner Schwierigkeiten.\n\nIch verband gerade meine Wunden, als mich die Vogelmenschen fanden und zurück in ihre Höhle schleiften, wo sie mich in diesen Käfig sperrten! Ich muss unbedingt zur Falkenwacht!", sourceObjective = "Beschützt die verwundete Blutelfenpilgerin auf Ihrem Weg zur Falkenwacht und sprecht dann mit Taleris Morgenblick.", progress = "Was braucht Ihr, {class}?", completion = "<Taleris ruft einige der Blutelfen aus dem Außenposten herbei.>\n\nSchafft sie herein und versorgt ihre Wunden!\n\n<Taleris wendet sich wieder Euch zu.>\n\nSie kann sich glücklich schätzen, dass Ihr sie noch rechtzeitig gefunden habt, {class}. Viel länger hätte sie dort draußen alleine nicht überlebt.\n\nKonntet Ihr verstehen, was sie gesagt hat?", sourceObjectiveStatus = "unverified-source-field" }
quests[9376] = { id = 9376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Pflicht eines Pilgers", description = "Diese verletzte Pilgerin schreit irgendwas von einem Beutel.\n\nHabt Ihr einen Beutel in der Nähe gesehen, als Ihr sie gefunden habt? Hmm...\n\nIhre Angreifer müssen sich damit aus dem Staub gemacht haben, als sie sie vertrieben hat. Die Stachelklauenfelshetzer aus der Schlucht im Süden sind bekannt dafür, dass sie einsame Reisende angreifen.\n\nWenn sie sich nicht beruhigt, kann ich Ihre Wunden nicht behandeln. Ihre Sturheit könnte sie das Leben kosten.\n\nGeht zur Staubstachelschlucht und haltet nach ihrem Lager Ausschau. Ich möchte wetten, dass sie ihn da verloren hat.", sourceObjective = "Die verletzte Blutelfpilgerin wurde von giftigen Stachelklauenfelshetzern angegriffen, als sie die Staubstachelschlucht erkunden wollte. Findet ihr Lager und haltet nach dem vermissten Beutel Ausschau.", progress = "Die Sache sieht nicht gut aus. So schafft sie es nie wieder auf die Straße. Habt Ihr den Beutel gefunden?", completion = "Vielen Dank, dass Ihr dies zurückgebracht habt, {name}. Ich weiß nicht, was der verletzten Pilgerin an diesem Beutel so wichtig ist, aber sie lässt keinen an sich heran, bis sie ihn wieder hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[9380] = { id = 9380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hatz nach mehr", description = "Ich sage Euch, sollte ich noch einen Brief von Eisenschmiede bekommen...\n\nHabt Ihr jemals versucht, jemandem etwas zu erklären, der nicht zuhört, {class}? Ich habe den Jungs in Eisenschmiede das von ihnen angeforderte Sphärenhundexemplar geschickt. Jetzt waren sie so frech und haben mir zurückgeschrieben, dass sie ein ganzes \"Rudel\" dieser Viecher möchten! Ein Rudel!\n\nIch habe ihnen also zu erklären versucht, dass Sphärenhunde Einzelgänger sind, aber es schert sie nicht. Ich bin es leid zu diskutieren. In der Gegend östlich der Festung findet Ihr sie. Beschafft sechs der besten und bringt sie hierher zurück?", sourceObjective = "Beschafft 6 unversehrte Sphärenhundkadaver und bringt sie zu Ausgrabungsleiter Murantus in der Ehrenfeste.", sourceObjectiveStatus = "unverified-source-field" }
quests[9381] = { id = 9381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treffsichere Pfeile", description = "Mit dem Zustrom von Pilgern und dem Vordringen der Allianz, war die Falkenwacht in letzter Zeit ein sehr geschäftiger Ort. In meiner freien Zeit stelle ich normalerweise Pfeile für die Waldläufer her. Leider habe ich schon lange keine Zeit mehr dazu gehabt, die für die Pfeilherstellung notwendigen Federn zu beschaffen.\n\nEs wäre mir ein paar Münzen wert, wenn Ihr die Schwanzfedern von Knochenhäutern für mich einsammeln würdet. In der Vergangenheit habe ich diese Geier oft über den Knochen verendeter Kreaturen, nördlich der Falkenwacht, ausfindig gemacht.", sourceObjective = "Sammelt 8 Schwanzfedern eines Knochenhäuters von den Knochenhäutergeiern und bringt sie Falknerin Drenna Flusswind in der Falkenwacht.", progress = "Habt Ihr alle Federn beisammen?", completion = "Die sollten ihren Zweck erfüllen. Ich hatte schon befürchtet, dass den Waldläufern bald die Pfeile ausgehen, doch nun muss ich mir darüber erstmal keine Sorgen mehr machen. Vielen Dank für Eure Hilfe, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9382] = { id = 9382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal der Grollhufe", description = "Grüße, {class}.\n\nIch bin sicher, dass Ihr auf Euren Reisen etwas von der Verderbtheit dieser Welt mitbekommen habt. Sie ist so allgegenwärtig, dass sie sogar die einheimischen Tiere verändert hat. Natürlich nur die, die sie überlebt haben.\n\nDie Grollhufe im Süden und Westen waren einst friedliche Weidentiere, aber die Verderbtheit hat sie mit einer unstillbaren Wut erfüllt. Der einzige Ausweg aus dieser Qual ist der Tod, auch wenn wir nur ungern ihr Blut vergießen. Helft Ihr mir dabei, das Leiden der borstigen Grollhufe zu beenden?", sourceObjective = "Tötet 15 borstige Grollhufe und kehrt dann zu Amaan dem Weisen im Tempel von Telhamat zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9383] = { id = 9383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein gewagter Plan", description = "Die Blutelfen verkörpern den völlig unverantwortlichen Umgang mit den Mächten der Magie, {class}. Sie kontrollieren die Magie nicht, nein, vielmehr sind sie ihre Sklaven und sie werden niemanden zwischen ihre Abhängigkeit und die magischen Energien kommen lassen, nach denen es ihnen dürstet. Die Blutelfen nutzen die Energien der Scherbenweltleerwandler, um ihre dämonische Magie zu wirken.\n\nIch habe einen Kristall mit einem Zauber aufgeladen, der es uns ermöglichen wird, einen Leerwandler zu neutralisieren und das magische Band zwischen ihm und dieser Welt zu zerschneiden. Ich habe die Leerwandler hauptsächlich in den Sphärenfeldern und südöstlich der Höllenfeuerzitadelle gesehen.", sourceObjective = "Wendet den geweihten Kristall auf einen verwundeten unkontrollierten Leerwandler an. Kehrt anschließend zu Elsaana beim Tempel von Telhamat zurück.", progress = "Habt Ihr die Magie des Kristalls gegen einen unkontrollierten Leerwandler eingesetzt?", completion = "Ihr habt Euch bewährt, {name}. Es scheint, als würde der Verwahrungskristall fürs Erste standhalten, allerdings weiß niemand wie lange. Wir werden ihn im Auge behalten und in der Zwischenzeit noch mehr Kristalle vorbereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[9384] = { id = 9384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nutzt das Licht", description = "Die Zeit ist gekommen, diesen Dämon zu vernichten. Ich empfehle Euch vorsichtig zu sein, {name}, denn es gibt noch vieles, dass Ihr noch nicht über die Leerwandler der Scherbenwelt wisst.\n\nBringt Rumatu dieses Gefäß, damit er sich um dessen Zerstörung kümmern kann. Beobachtet den Vorgang genau und berichtet mir, sobald der Prozess abgeschlossen ist.", sourceObjective = "Bringt den leuchtenden geweihten Kristall zu Rumatu beim Tempel von Sha'naar, damit er den darin eingeschlossenen Dämon mit den Kräften des Lichts zerschlagen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[9385] = { id = 9385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tobende Felshetzer", description = "Also schickt uns die Ehrenfeste hierher, um mit den Arakkoa fertig zu werden, und wir bauen unser Lager auf und denken uns hey, schön hier. Wir hatten ja keine Ahnung, dass wir so nahe bei den Stachelklauenfelshetzern sind.\n\nSie sind erbarmungslose Raubtiere und haben jegliche Arbeit unsererseits zunichte gemacht. Wenn Ihr Euch darum kümmert, würde ich Euch bezahlen. Habt Ihr Lust?", sourceObjective = "Tötet 10 Stachelklauenfelshetzer und kehrt anschließend zu Gremni Langbart auf der Höllenfeuerhalbinsel zurück.", progress = "Macht Ihr Fortschritte im Kampf gegen die Felshetzer?", completion = "Gut gemacht, {name}. Das wird den Biestern zeigen, wer hier der Boss ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[9386] = { id = 9386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Licht im Dunkeln", description = "Ihr seid ziemlich eifrig, oder? Solltet Ihr Euch noch einmal in die Tiefen wagen, so bin ich gerne bereit, Euch dafür zu belohnen.\n\nSucht die Freudenfeuer in Stratholme, Scholomance, dem Düsterbruch und den Hallen der Schwarzfelsspitze auf. Ich erwarte Eure Rückkehr, {name}.", sourceObjective = "Findet und berührt die Freudenfeuer innerhalb der Schwarzfelsspitze, dem Düsterbruch, Scholomance und Stratholme. Sprecht dann mit dem Flammenbewahrer.", sourceObjectiveStatus = "unverified-source-field" }
quests[9387] = { id = 9387, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Quelle der Verderbtheit", description = "Unverderbte Draenei, wie dieser unglückliche Geselle hier, sind begabte Helden des Lichts. Welche Verderbtheit hat wohl ihr großartiges Volk dazu gebracht, sich zu Zerschlagenen und Verirrten zurückzuentwickeln?\n\nMir ist eine Theorie zu Ohren gekommen, die besagt, dass die Mutation von teuflischen Energien ausgelöst wurde. Ich würde diese Theorie gerne überprüfen.\n\nNordwestlich von hier findet Ihr die Ruinen von Sha'naar. Dort befinden sich einige einfache Zerschlagene unter dem Befehl der Zuchtmeister der Illidari. Bringt mir die dämonischen Essenzen der Zuchtmeister, damit ich sie an diesem Draenei ausprobieren kann.", sourceObjective = "Reist zu den Ruinen von Sha'naar auf der Höllenfeuerhalbinsel und besorgt 5 dämonische Essenzen von den Zuchtmeistern der Illidari. Kehrt zu Apotheker Azethen in der Falkenwacht zurück, wenn Ihr die Aufgabe erfüllt habt.", progress = "Habt Ihr die Proben bekommen?", completion = "Ihr wart mir eine große Hilfe, {name}. Nun wollen wir sehen, was wir von unserem blauen Freund lernen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[9388] = { id = 9388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lodernde Flammen in Kalimdor", description = "Heute lodern zahlreiche Flammen in der Welt, {name}. Die Feuer, die am schwierigsten zu unterhalten sind, leuchten grün; werden sie nicht ständig beaufsichtigt, brennen sie nicht lange. Versichert Euch für unseren Flammenbewahrer, dass die Smaragdfeuer in Kalimdor auch weiterhin lodern, eh?\n\nIhr findet sie in der Nähe von Ratschet im Brachland, unweit der Meistergleve in Dunkelküste, im Wald des Eschentals bei der Brücke nahe des Außenpostens der Silberschwingen und entlang der Hauptstraße im Steinkrallengebirge, in der Nähe der Straße, die zur Scherwindklippe führt.", sourceObjective = "Sucht die Freudenfeuer im Eschental, dem Brachland, der Dunkelküste und dem Steinkrallengebirge auf. Sprecht anschließend mit dem Flammenbewahrer.", completion = "Ahhh, sie brennen also noch. Das freut mich; es wäre nicht gut, wenn die Feuer vorzeitig erlöschen würden. Ihr habt gute Arbeit geleistet, {name}. Nehmt dies mit meinem Segen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9389] = { id = 9389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lodernde Flammen in den östlichen Königreichen", description = "Die Feuer des Sonnenwendfests lassen das Land traditionsgemäß im Licht unzähliger Flammen erstrahlen. Manche behaupten, dass die grünen Flammen die besten seien, da sie so schwierig zu unterhalten sind und eine solch ungewöhnliche Farbgebung haben.\n\nVersichert Euch für unseren Flammenbewahrer, dass die Feuer in den östlichen Königreichen auch weiterhin lodern. Ihr findet sie in der Nähe von Dun Modr im Sumpfland, unweit von Lohenscheit im Silberwald, bei den Klippen zum Leuchtturm in Westfall und nahe dem zerstörten Turm im Vorgebirge des Hügellands.", sourceObjective = "Sucht die Freudenfeuer im Vorgebirge des Hügellands, im Silberwald, in Westfall und dem Sumpfland auf. Sprecht anschließend mit dem Flammenbewahrer.", completion = "Ihr seid also wieder da und habt die Smaragdflammen dieser Welt gesehen. Was sagt Ihr, mh? Ein mit Sicherheit seltener und wunderschöner Anblick. Natürlich weiß ich, dass eine handfeste Belohnung mehr Anklang findet... also bitte, nehmt dies für Eure Mühen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9390] = { id = 9390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach Sedai", description = "Hört mein Leid, {class}. Mein Bruder Sedai ist schon vor längerer Zeit losgezogen, um den Orcs beim Posten der Mag'har eine Botschaft zu übermitteln. Als ein unverbesserlicher Idealist war er der Meinung, dass der Zeitpunkt nun gekommen sei, unsere Differenzen beizulegen und einen Friedensvertrag mit ihnen auszuhandeln.\n\nEr wird jetzt schon seit Tagen vermisst und ich befürchte das Schlimmste.\n\nWürdet Ihr für mich nach ihm Ausschau halten, damit ich endlich wieder Ruhe finde? Sedai müsste sich irgendwo in der östlichen Umgebung aufhalten.", sourceObjective = "Anachoret Obadei möchte, dass Ihr östlich von hier auf der Höllenfeuerhalbinsel nach seinem Bruder Sedai Ausschau haltet.", completion = "Ihr habt den Leichnam eines jungen Paladins der Draenei gefunden. Es scheint, als hätte ihn jemand hinterrücks erschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9391] = { id = 9391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Weg kennzeichnen", description = "Nachdem die Felsklauenpopulation ausgedünnt ist, müssen wir die sichere Passage nur noch für unsere Pilger kenntlich machen. Nehmt diese Fackel und begebt Euch erneut in die große Kluft. Sucht dort die drei Leuchtsignale, die den Verlauf des Pfads im Osten kennzeichnen.\n\nEntzündet die drei Signale und kehrt anschließend zu mir zurück. Doch seid gewarnt, das Entzünden eines Leuchtsignals zieht unweigerlich die Felsklauen aus der Umgebung an.", sourceObjective = "Waldläuferhauptmann Venn'ren an der Falkenwacht möchte, dass Ihr auf der Höllenfeuerhalbinsel die große Kluft aufsucht und dort das südliche Leuchtsignal, westliche Leuchtsignal und das zentrale Leuchtsignal entzündet. Kehrt anschließend mit der brennenden Fackel zu ihm zurück.", progress = "Habt ihr getan, worum ich Euch gebeten habe, {name}?", completion = "Obwohl die große Kluft noch immer ein gefährlicher Ort ist, gibt sie einen brauchbaren Pfad für unsere Pilger ab.\n\nEin derartiger Akt der Verzweiflung ist unvermeidlich, solange die Allianz weiterhin sämtliche ein- und ausgehenden Straßen zur Falkenwacht beobachtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[9392] = { id = 9392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildung zum Schurken", description = "Während Ihr in Eurer Klasse weiter aufsteigt, werdet Ihr sicher die Ausbildung, die Euch der Lehrer Eurer Klasse anbietet, nutzen wollen. Der Lehrer für junge Schurken hier auf der Insel der Sonnenwanderer ist Pfadpirscher Avokor. Sprecht mit Avokor, um herauszufinden, welche Ausbildung er Euch anbieten kann. Die Ausbildung hat ihren Preis, bringt also ein paar Münzen mit Euch.\n\nAvokor - wie alle anderen Lehrer auf der Insel der Sonnenwanderer auch - ist innerhalb des Sonnenturms, auf der unteren Ebene, anzutreffen.", sourceObjective = "Sprecht mit Pfadpirscher Avokor - dem Schurkenlehrer - innerhalb des Sonnenturms auf der Insel der Sonnenwanderer.", completion = "Die Schatten haben mir Euren Namen zugeflüstert, {name}. Man sagt, dass Ihr nach jemandem sucht, der erfahren ist und Euch zeigt, wo's lang geht - jemandem wie mich. Ich bin durchaus gewillt, ja, aber es wird Euch jedes Mal etwas kosten, wenn ich Euch etwas beibringe. Ich werde Euch alles lehren, was es als Schurke zu beherrschen gilt.\n\nSolltet Ihr jedoch einmal auf frischer Tat ertappt werden, dann hat diese Unterhaltung nie stattgefunden, verstanden? Geht jetzt los und zeigt mir, was Ihr drauf habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[9393] = { id = 9393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildung zum Jäger", description = "Während Ihr in Eurer Klasse weiter aufsteigt, werdet Ihr sicher die Ausbildung, die Euch der Lehrer Eurer Klasse anbietet, nutzen wollen. Die Lehrerin für junge Jäger hier auf der Insel der Sonnenwanderer ist Waldläuferin Sallina. Sprecht mit Sallina, um herauszufinden, welche Ausbildung sie Euch anbieten kann. Die Ausbildung hat ihren Preis, bringt also ein paar Münzen mit Euch.\n\nSallina - wie alle anderen Lehrer auf der Insel der Sonnenwanderer auch - ist innerhalb des Sonnenturms, auf der unteren Ebene, anzutreffen.", sourceObjective = "Sprecht mit Waldläuferin Sallina - der Jägerlehrerin - innerhalb des Sonnenturms auf der Insel der Sonnenwanderer.", completion = "{name}, sind Eure Augen so scharf wie die eines Falken, Eure Bewegungen so geschickt wie die eines Affen oder seid Ihr etwa so flink wie ein Gepard? Auf mich trifft all das zu und mit der richtigen Ausbildung vielleicht auch auf Euch. Ein Jäger zeichnet sich dadurch aus, dass er die Kreaturen dieser Welt zu beherrschen vermag, er seine Waffen treffsicher zu führen weiß und er in Situationen überlebt, die für andere den Tod bedeuten.\n\nIch werde Euch unterweisen, wenn Ihr auch wirklich dazu gewillt seid. Allerdings hat dies seinen Preis. Sollen wir beginnen?", sourceObjectiveStatus = "unverified-source-field" }
quests[9394] = { id = 9394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo ist Wyllithen?", description = "Der Nachtschimmergrundbewahrer ist verschwunden! Jemand muss vergessen haben, ihm zu sagen, dass er den Ort verlassen sollte, als der Magister und alle anderen es taten. Ich weiß, dass er sich noch irgendwo hier auf dem Grund aufhält, aber ich getraue mich nicht, selbst nach ihm zu sehen, da sich hier so viele magische Kreaturen herumtreiben.\n\nKönnt Ihr ihn für mich finden, {class}? Bitte seht nach, ob er in Ordnung ist.", sourceObjective = "Findet Grundbewahrer Wyllithen beim Nachtschimmergrund im Immersangwald.", completion = "Wer seid Ihr? Ihr seid keiner von den Lehrlingen des Magisters, das steht fest!\n\nMan hat Euch sicherlich hierher geschickt, um mir dabei zu helfen, wieder Ordnung in dieses Chaos zu bringen!", sourceObjectiveStatus = "unverified-source-field" }
quests[9395] = { id = 9395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saltherils Hafen", description = "Ich schwöre, dass ich jemandem einen Feuerball verpasse, wenn Lord Saltheril mir auch nur noch eine Lieferanfrage für seine endlosen Feste schickt. Sehe ich verdammt nochmal wie ein Festtagsplaner aus?! Unter uns gesagt, dieser Verrückte und seine Bande von Speichelleckern scheinen bis heute zu verdrängen, dass wir unter ständiger Belagerung stehen!\n\nEinige von uns sind doch tatsächlich mit, äh, ich weiß nicht... der verdammten Verteidigung unseres Königreichs, Quel'Thalas, beschäftigt?! Würdet Ihr mir einen Gefallen tun, {class}? Seid doch so gut und reist für mich nach Saltherils Hafen und seht zu, dass er endlich Ruhe gibt! Es ist gleich die Straße runter, Richtung Westen.", sourceObjective = "Sprecht mit Lord Saltheril in Saltherils Hafen im Immersangwald.", completion = "Ah, Magistrix Morgenwandler hat zu guter Letzt doch noch auf meine simple Anfrage reagiert. Beizeiten werde ich Ihr Benehmen mit dem Lordregenten erörtern. Sie ist eine recht ungehobelte Person!\n\nNichts, worüber Ihr Euch Sorgen machen müsstet. Nun, wo Ihr schon mal hier seid, besteht vielleicht die Möglichkeit, dass ich endlich meine Vorräte für das Fest bekomme, auf die ich schon so lange warte.", sourceObjectiveStatus = "unverified-source-field" }
quests[9396] = { id = 9396, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Magie der Arakkoa", description = "Die Scherbenwelt birgt viele Geheimnisse, {name}. Es ist nur noch eine Frage der Zeit, bis wir sie alle enträtselt haben.\n\nDas Volk der halb Vogel, halb menschlichen Arakkoa verfügt über uraltes arkanes Wissen, welches sich als sehr nützlich für unsere Erforschung dieser Welt erweisen würde. Reist nach Süden zum Haal'eshbau. Nehmt alle magischen Rollen an Euch, die Ihr bei den Haal'eshi finden könnt und bringt sie mir.", sourceObjective = "Bringt 4 Rollen der Haal'eshi zu Arkanist Calesthris Morgenstern bei der Falkenwacht auf der Höllenfeuerhalbinsel.", progress = "Habt Ihr die Schriftrollen, {name}?", completion = "Gut gemacht, {name}. Die Geheimnisse der Scherbenwelt werden sich nicht lange vor uns verstecken können.\n\nEs ist unser Schicksal, die Meister dieser Welt zu werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9397] = { id = 9397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kommt ein Vogel geflogen", description = "Die Arakkoa der Haal'eshi haben eine wunderschöne Vogelart, den Kaliri, domestiziert.\n\nMir ist es gelungen, ein junges Kalirimännchen einzufangen, und sie scheinen zähmbar zu sein. Die weiblichen Exemplare sind deutlich seltener, aber wenn es mir gelänge, eines davon zu ergattern, sollte ich in der Lage sein, sie selbst zu züchten. Es muss jedoch ein junges Weibchen sein, fast noch ein Küken. Ein alter Wildvogel würde die Gefangenschaft nicht lange überleben.\n\nNehmt diesen Käfig und reist nach Süden zum Haal'eshbau. Sucht nach Eiern, die kurz vor dem Schlüpfen stehen. Wenn Ihr mir ein junges Weibchen zurückbringt, werde ich Euch fürstlich belohnen.", sourceObjective = "Reist zum Haal'eshbau auf der Höllenfeuerhalbinsel und durchsucht die Kalirinester nach einem jungen Kaliriweibchen. Benutzt den leeren Vogelkäfig, um es zu fangen, und kehrt anschließend zu Falknerin Drenna Flusswind in der Falkenwacht zurück.", progress = "Ihr seid zurück. Habt Ihr mir ein Kaliriweibchen mitgebracht?", completion = "Ihr habt es geschafft! Ihr habt ein junges Weibchen gefangen!\n\nSie ist wundervoll. Vielen, vielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9398] = { id = 9398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tödliche Raubtiere", description = "Die Zerschlagenen in der Scherbenwelt haben unendlich viel Grausamkeit ertragen müssen. Kein Wunder, dass sie sofort nach der Öffnung des Dunklen Portals scharenweise in der Hoffnung, diesem Land entfliehen zu können, dorthin gepilgert sind.\n\nZum Pech für unsere verwirrten Brüder und Schwestern sind sie für die Felsklauen, die in der großen Kluft leben, eine leichte Beute. Geht dort hin und vernichtet einige der Felsklauen, damit unseresgleichen eine Chance hat.", sourceObjective = "Späher Vanura im Tempel von Telhamat auf der Höllenfeuerhalbinsel möchte, dass Ihr 8 Steinsichelwelpen und 4 Steinsichelalpha tötet.", completion = "Ihr habt gute Arbeit geleistet, {name}. Es ist immer schlimm, wenn Töten die einzige Möglichkeit ist, die bleibt, sogar wenn es sich um so gefährliche Biester wie die Steinsichelklauen handelt.\n\nIhr habt meinen Dank, dass Ihr diese grausame Aufgabe erledigt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9399] = { id = 9399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Grausamkeit der Zuchtmeister", description = "Sicherlich glaubt auch Ihr, dass die meisten Zerschlagenen bösartig sind, nicht wahr? In Wahrheit mangelt es vielen nur an geistiger Führung.\n\nIch war ebenfalls verloren, bevor ich die Omenai getroffen habe.\n\nUnser Verstand litt sehr unter der dämonischen Magie der Orcs. Man kann uns leicht in die Irre führen und ausnutzen.\n\nDämonen, die mit Illidan verbündet sind, überfallen täglich die Höllenfeuerhalbinsel und verschleppen Unseresgleichen als Sklaven. Doch mit den Omenai kam die Hoffnung. Reist zu den Ruinen von Sha'naar, südwestlich von hier, und tötet die Zuchtmeister der Illidari, damit mein Volk endlich wieder frei ist!", sourceObjective = "Reist zu den Ruinen von Sha'naar und erschlagt 4 Zuchtmeister der Illidari. Kehrt anschließend zu Ikan zum Tempel von Telhamat auf der Höllenfeuerhalbinsel zurück.", completion = "Ihr habt es geschafft! Wir stehen tief in Eurer Schuld, {name}. Seht Euch nur all die Ankömmlinge des Lumpenpacks an.\n\nUnter meiner geistigen Führung werden sie alles über die alten Traditionen lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9400] = { id = 9400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Assassine", description = "{name}, wir haben erst kürzlich einen Plan zur Ermordung unseres Gesandten in der Falkenwacht aufgedeckt. Spione der Höllenfeuerzitadelle haben von unseren Plänen, eine Expedition zur Wacht auszusenden, erfahren und einen Hinterhalt vorbereitet.\n\nUnsere Späher berichteten mir, dass ein Assassine namens Krun Rückenbrecher auf der Straße nördlich der Zitadelle in Stellung gegangen ist. Begebt Euch dorthin und tötet diesen Assassinen. Macht den Höllenorcs klar, dass man mit uns keine Spielchen treibt.", sourceObjective = "Nazgrel möchte, dass Ihr zu der Straße nördlich der Höllenfeuerzitadelle reist und nach einem Assassinen namens Krun Rückenbrecher Ausschau haltet.", completion = "Der Leichnam stimmt mit der Beschreibung von Krun Rückenbrecher, dem Assassinen der Höllenfeuerzitadelle, überein. Als Ihr den noch warmen Körper umdreht, erblickt Ihr eine Steinaxt, die in seinem Rücken steckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9401] = { id = 9401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine seltsame Waffe", description = "Ihr zieht die Steinaxt aus dem toten Körper, um sie eingehender zu untersuchen. Irgendetwas an der Verarbeitung der Axt ist ungewöhnlich.\n\nSie scheint orcischen Ursprungs zu sein und dennoch besteht sie aus einem Material, das Ihr noch nie zuvor gesehen habt. Nazgrel wäre bestimmt daran interessiert, die Axt weiter zu untersuchen.", sourceObjective = "Bringt die schwere Steinaxt zu Nazgrel in Thrallmar auf der Höllenfeuerhalbinsel.", progress = "Sagt mir, ist der Assassine tot?", completion = "Er wurde mit dieser Waffe getötet? Das ist unmöglich!\n\nHaben wir... haben wir sie tatsächlich gefunden?", sourceObjectiveStatus = "unverified-source-field" }
quests[9402] = { id = 9402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fangt!", description = "So... Ihr seid {name}, oder? Fühlt Euch nicht geschmeichelt, ich kenne Euren Namen, einer meiner Schüler ist bei Euch herumscharwenzelt und plappert ununterbrochen.\n\nHmm... wenn Ihr <ihn/sie> beeindrucken möchtet, warum helft Ihr mir dann nicht aus? Auf dem Grund des Stillwispertümpels hinter mir liegt eine Azurphiole. Taucht in die Tiefe, schnappt sie Euch und bringt sie zu mir.", sourceObjective = "Taucht auf den Grund des Stillwispertümpels und holt die Azurphiole für Instrukteur Antheol.", progress = "Wie ist das Wasser?", completion = "Oh, gut gemacht... ich sagte Ihr sollt in den Tümpel springen und Ihr habt es getan. Ich kann mir gut vorstellen, was Ihr tun würdet, wenn einer Eurer Freunde Euch um etwas bitten würde.\n\nWollt Ihr für Eure Mühe belohnt werden, dann ist es das: macht keinen Finger krumm, bevor Ihr nicht wisst, was dabei für Euch herausspringt. Der Geist des Magiers ist seine stärkste Waffe. Vergesst das nicht und versucht Euren ein wenig mehr anzustrengen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9403] = { id = 9403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das reinste Wasser", description = "Jetzt, da Ihr eine kleine Lektion gelernt habt, bitte ich Euch etwas Handfesteres an. Es betrifft Eure Fähigkeiten der Selbstverteidigung. Ihr solltet natürlich nur im äußersten Notfall von Nahkampftechniken Gebrauch machen, aber deshalb sollte man trotzdem nicht unvorbereitet sein.\n\nIch kann Euch bei der Herstellung eines Stabs helfen, der einem Magier Eures Ranges gerecht wird. Nehmt die Phiole, die Ihr für mich besorgt habt, und füllt sie bei den Elrendarfällen auf. Folgt einfach dem Fluss südöstlich von hier.", sourceObjective = "Instrukteur Antheol möchte, dass Ihr die Azurphiole bei den Elrendarfällen auffüllt.", progress = "Nur das Wasser von den Elrendarfällen hat die erforderliche Reinheit für den Gebrauch von Magie. Habt Ihr es?", completion = "Mal sehen, was Ihr mir gebracht habt...\n\n<Er hält die Phiole gegen das Licht und studiert sie genau.>\n\nJa, das sollte es sein. Gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9404] = { id = 9404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch lebendig", description = "Ihr habt vielleicht die wandelnden Bäume nahe der Elrendarfälle bemerkt. Als Behüter der Natur sind sie mit urzeitlicher Magie erfüllt, die wir mithilfe des reinem Wassers, das Ihr mir gebracht habt, umformen und für unsere Zwecke verwenden können.\n\nUnglücklicherweise sind die Waldbehüter knorrige und verdrehte Kreaturen, so dass Ihr womöglich erst einige töten müsst, bevor Ihr einen brauchbaren Zweig findet.", sourceObjective = "Tötet die Immersangwaldbehüter bis Ihr einen lebendigen Zweig für Instrukteur Antheol findet.", progress = "Habt Ihr den lebendigen Zweig? Schnell, gebt ihn mir!", completion = "Ihr seid meiner Bitte nachgekommen, {name}. Ihr könnt Eure Belohnung jetzt entgegennehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9405] = { id = 9405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Anliegen des Kriegshäuptlings", description = "Wie Ihr wisst, steht der Kriegshäuptling aus ganzer Kraft hinter dieser Expedition und das aus gutem Grund. Dies ist unsere Heimatwelt. Hier liegen unsere Wurzeln.\n\nDiese Reise hat für Orcs und Blutelfen gänzlich unterschiedliche Bedeutung. Für sie ist es die Suche nach dem gelobten Land. Für uns ist es die Rückkehr in unsere lange verlorene Heimat.\n\nWer auch immer diese Axt gefertigt hat, ist mit den alten Traditionen vertraut. Wir müssen Kontakt zu ihnen aufnehmen. Diese Angelegenheit ist zu wichtig, als dass wir reguläre Methoden des Aufspürens verwenden. Zeigt Scharfseherin Regulkut die Waffe; sie wird wissen, was zu tun ist.", sourceObjective = "Bringt die schwere Steinaxt zu Scharfseherin Regulkut in Thrallmar auf der Höllenfeuerhalbinsel.", progress = "Sagt mir, wonach Ihr sucht, damit ich Euch bei der Suche unterstützen kann.", completion = "Ich verstehe Nazgrels Anliegen, {class}. Sagt nichts weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[9406] = { id = 9406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Mag'har", description = "Diese Neuigkeiten, die Ihr von jenseits des Portals bringt; Ihr wollt mir ernsthaft Glauben machen, dass der Sohn Durotans nun über die jenseitigen Länder herrscht? Frei vom dämonischen Einfluss? Und nun sind seine Leute in diese Welt zurückgekehrt?\n\nUm euretwillen hoffe ich, dass das nicht irgendein perfider Witz sein soll, {class}. Es ist schwer zu beschreiben, was dies für mein Volk bedeutet. Ich werde umgehend eine Botschaft nach Nagrand schicken! Höllschrei muss davon erfahren.\n\nBringt diesen Brief zu Eurem Anführer in Thrallmar. Sagt ihm, die Mag'har heißen Euch willkommen!", sourceObjective = "Bringt den Brief von den Mag'har zu Nazgrel in Thrallmar auf der Höllenfeuerhalbinsel.", progress = "Was habt Ihr für uns, {name}?", completion = "Seid Ihr sicher? Wahre Orcs, hier auf der Höllenfeuerhalbinsel! Das sind große Neuigkeiten, {name}.\n\nDer Kriegshäuptling muss umgehend davon in Kenntnis gesetzt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9407] = { id = 9407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch das Dunkle Portal", description = "Viele Jahre stand das Dunkle Portal still... vergessen. Aber nun ist es nicht mehr still.\n\nNachdem der Angriff der Dämonen aufgehalten wurde, haben unsere Truppen das Portal durchschritten und sich den Dämonen auf ihrem eigenen Gebiet gestellt!\n\nNun sind wir in einem wilden Krieg gefangen, und einige sind der Meinung, dass wir ihn nicht gewinnen können. Es ist also unsere Pflicht und unser grausames Vergnügen, unsere Feinde in der Scherbenwelt zu bekämpfen und unseren Sieg zu sichern, {name}.\n\nWenn Ihr uns helfen wollt, meldet Euch unverzüglich bei Generalleutnant Orion. Er erwartet Euch in der Scherbenwelt...", sourceObjective = "Reist durch das Dunkle Portal und meldet Euch bei Generalleutnant Orion. Er erwartet Euch auf der anderen Seite - in der Scherbenwelt.", completion = "Unser Expeditionskorps kam ohne Probleme durch das Portal und hat ein neues Lager namens Thrallmar errichtet. Aber wie Ihr sehen könnt ist die Brennende Legion eingefallen und hat uns von unseren Brüdern abgeschnitten. Die Dämonen sind eindeutig darauf aus, das Dunkle Portal einzunehmen und uns daran zu hindern, Verstärkung aus Azeroth zu holen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9408] = { id = 9408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergessene Helden", description = "Auch wenn es mich traurig macht, dass wir so viele Soldaten bei dem Versuch, das Portal zu durchbrechen, verloren haben, erfüllt es mich doch mit Stolz, dass das ursprüngliche Expeditionskorps noch am Leben ist.\n\nIch kann es kaum glauben, aber dort stehen sie - ein Zeichen für die Entschlossenheit der Allianz.\n\nIn dieser Festung steht einer unserer großartigsten Helden: Danath Trollbann! Geht zu ihm, {class}. Er hat schon all unsere Soldaten getroffen und mit ihnen gesprochen. Er möchte Euch sicher kennenlernen.", sourceObjective = "Sprecht mit Truppenkommandant Danath Trollbann in der Ehrenfeste.", sourceObjectiveStatus = "unverified-source-field" }
quests[9409] = { id = 9409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eilige Lieferung!", description = "Da Ihr jetzt alles besorgt habt, was zum Wiederaufladen der Heilkristalle benötigt wird, müsst Ihr die Phiolen zu unserem Priester Zalduun bringen. Er kümmert sich um die Verwundeten innerhalb der zentralen Kammer des Schiffes.", sourceObjective = "Bringt die Phiolensammlung zu Zalduun bei der Absturzstelle im Am'mental.", progress = "Hallo, {class}. Was habt Ihr da? Ist das für mich?", completion = "Gute Arbeit! Das wird die erschöpften Heilkristalle wieder aufladen.\n\nDa Ihr nun schon einmal hier seid... ich hätte da noch eine Aufgabe für Euch, solltet Ihr gewillt sein?", sourceObjectiveStatus = "unverified-source-field" }
quests[9410] = { id = 9410, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirituelle Führung", description = "Selbst die Sinne unserer besten Spürwölfe können sich irren, {name}. Die Geister jedoch, haben eine andere Sicht auf diese Welt. Das Wesen, welches Ihr beschwören werdet, wird die von Euch gesuchte Person ausfindig machen, denn es spürt nicht dem Geruch des Gesuchten hinterher sondern seiner Essenz.\n\nGeht jetzt, {class}, nehmt dieses Totem mit Euch und benutzt es an dem Ort, wo Ihr die Steinaxt gefunden habt.", sourceObjective = "Verwendet das Wolfstotem an dem Ort, wo Ihr Krun Rückenbrechers Leichnam gefunden habt und folgt dem Ahnengeistwolf.", progress = "Ihr könnt froh sein, dass Ihr noch lebt.", completion = "Wer seid Ihr, dass Ihr hier so einfach unangekündigt umherwandert? Ich habe meine Männer nur zurückgehalten, weil Ryga die Anwesenheit der Geister in Eurer Nähe verspürte.\n\nIhr könnt frei sprechen, doch wählt Eure Worte mit Bedacht. Wir vertrauen normalerweise keinen Fremden, die hier so nah bei der Zitadelle umherstreifen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9415] = { id = 9415, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung bei Marschall Himmelswand", description = "Gehört Ihr zu Marschall Himmelswands neuen Rekruten? Natürlich.\n\nAuf was wartet Ihr noch? Gute Soldaten verlieren ihr Leben in der Wüste. Freut es Euch nicht, bald dazuzugehören?\n\nLos jetzt, macht Euch auf den Weg... und trocknet dabei nicht aus.", sourceObjective = "Sprecht mit Marschall Himmelswand beim Lager der Allianz in der Nähe des Zoraschwarmbaus.", completion = "Die Allianz braucht jeden tauglichen Rekrut, den sie bekommen kann. Die Horde hat ständig Verstärkung vom nördlichen Kontinent bekommen, wir mussten kämpfen, um überhaupt standzuhalten.\n\nLasst Euch die Lage von mir schildern.", sourceObjectiveStatus = "unverified-source-field" }
quests[9416] = { id = 9416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung bei General Kirika", description = "Ihr müsst zu General Kirikas neuen Rekruten gehören. Es wurde Zeit, dass Ihr kommt. Der Truppenverschleiß in der Wüste ist hoch.\n\nDie Zwerge haben tagtäglich Verstärkung bekommen, wir können es uns nicht leisten in unserem Kampf um Ressourcen in Silithus an Boden zu verlieren.\n\nLasst Euch vom General weitere Anweisungen geben. Ich muss Euch Rekruten lediglich finden, nicht ausbilden.", sourceObjective = "Sprecht mit General Kirika beim Lager der Horde in der Nähe des Regalschwarmbaus.", completion = "Es ist gut, dass Ihr hier seid, aber wir haben keine Zeit für überflüssige Worte. Was Ihr braucht, sind Anweisungen, und dann müsst Ihr losziehen.\n\nHört gut zu.", sourceObjectiveStatus = "unverified-source-field" }
quests[9417] = { id = 9417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Arakkoabedrohung", description = "Die Arakkoa sind hochintelligente Wesen... gerissen wie ein Gnom. Nur, dass sie über ein ausgesprochen aggressives Gemüt und sehr mächtige Magie verfügen.\n\nIn letzter Zeit haben sie häufiger Patrouillen der Ehrenfeste überfallen, was auch der Grund für unsere Anwesenheit hier ist. Wisst Ihr, Mirren und ich sind weltbekannte Scharfschützen, ja, das sind wir! Allerdings sind wir eher auf Federvieh und Turniere spezialisiert... nicht auf diese Blitze schleudernden Vogelmenschen.\n\nWas sagt Ihr, greift Ihr uns in dieser Sache etwas unter die Arme? Ihr findet den Haal'eshbau im Südwesten.", sourceObjective = "Gremni Langbart auf der Höllenfeuerhalbinsel möchte, dass Ihr 4 Windspäher der Haal'eshi und 6 Krallenwachen der Haal'eshi tötet.", completion = "Fantastische Arbeit, {name}! Ich ernenne Euch hiermit zum Langbart ehrenhalber.\n\nBleibt noch ein Weilchen und trinkt etwas mit uns!", sourceObjectiveStatus = "unverified-source-field" }
quests[9418] = { id = 9418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Avruus Kugel", description = "<Als Ihr die Kugel näher an Euer Ohr haltet, hört Ihr, wie Euch eine Stimme anspricht.>\n\nIhr seid kein Arakkoa, wie ich spüre. Deswegen werde ich versuchen, Euch einen Handel für meine Freiheit vorzuschlagen. Mein Name ist Aeranas. Ich regierte einst über die östlichen Winde. Der Magier der Haal'eshi, Avruu, hat mich in dieser Kugel eingefangen.\n\nSucht den Altar der Arakkoa, mit dessen Hilfe sie mich versklavt haben. Er ist südöstlich vom Bau der Arakkoa versteckt. Nähert Euch ihm mit der Kugel und gebt sie mir, sobald ich frei bin. Als Ausgleich für meine Freiheit werde ich Euch einen mächtigen Schatz geben!", sourceObjective = "Bringt Avruus Kugel zum Altar der Haal'eshi südöstlich des Haal'eshbaus auf der Höllenfeuerhalbinsel und gebt sie Aeranas, sobald er frei ist.", progress = "Endlich habe ich meine Freiheit wieder!", completion = "Mit dieser Kugel erlange ich meine Freiheit wieder. Nehmt Eure Belohung, Sterblicher, auf dass meine Schuld bezahlt sei.", sourceObjectiveStatus = "unverified-source-field" }
quests[9419] = { id = 9419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchkämmen der Wüste", description = "Wir hatten vor Kurzem herausgefunden, dass die Horde die Wüste von Silithus nach Ressourcen abgesucht hat, schenkten dem Ganzen aber keine besondere Beachtung. Wir dachten, es wäre die Sache nicht wert, eine größere Anzahl von Soldaten in dieser Bruthitze zu stationieren.\n\nWie dem auch sei, wir haben die Wichtigkeit dieser Ressourcen erkannt und versuchen nun, um jeden Preis aufzuholen.\n\nWenn Ihr uns unterstützen wollt, müsst Ihr in die Wüste gehen, dort nach Silithyst suchen und diesen anschließend hierher bringen.", sourceObjective = "Findet Silithyst, bringt es zum Silithystextraktor und sprecht anschließend mit Marschall Himmelswand beim Lager der Allianz in der Nähe des Zoraschwarmbaus.", progress = "Seid da draußen auf der Hut und beeilt Euch besser. Wir haben keine Zeit zu verlieren.", completion = "Dem Licht sei Dank, Eure Suche war erfolgreich.\n\nHätten wir nur eher damit begonnen, dann wären wir jetzt nicht in einer so verzweifelten Notlage. Wir müssen verhindern, dass die Schätze der Wüste in die Hände der Horde fallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9420] = { id = 9420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feinste Daunen", description = "Die Arakkoa das Haal'eshbaus südlich von hier züchten eine besonders prächtige Art von Vögeln, namens Kaliri. Ihre Federn würden mir in den Handelsposten Azeroths einen ganz schönen Batzen Gold einbringen. Denkt nur an all das viele Bier, das ich mir leisten könnte!\n\nIch sag Euch was, bringt mir eine Ladung Kalirifedern und ich gebe Euch meinen Hut. Was sagt Ihr dazu? So einen Hut wie diesen hier, werdet Ihr nirgendwo sonst finden! Sind wir im Geschäft?", sourceObjective = "Mirren Langbart auf der Höllenfeuerhalbinsel möchte, dass Ihr ihm 8 Kalirifedern von den Kaliris im Haal'eshbau bringt.", progress = "Habt Ihr die Kalirifedern, {class}?", completion = "Ihr habt Euren Teil der Abmachung erfüllt. Ich schätze, Geschäft ist Geschäft!\n\nHier, mein Freund. Passt gut auf ihn auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[9421] = { id = 9421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildung zum Schamanen", sourceObjective = "Ich bin Firmanvaar und mich aufzusuchen war weise von Euch. Ich bin dazu berufen, Schamanen den richtigen Weg zu weisen, besonders denen, die wie Ihr noch unerfahren sind.\n\nDer Schamanismus wird von uns {race} gerade erst wiederentdeckt, {name}. Ihr seid wahrhaft mutig, dieser Lehre zu folgen, denn unter Unseresgleichen wird sie mit Argwohn betrachtet.\n\nIch bin hier, solltet Ihr meine Unterweisung wünschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9422] = { id = 9422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchkämmen der Wüste", description = "Wir haben die Wüste von Silithus bereits seit einiger Zeit nach Kristallressourcen durchkämmt. Die einzigen Gefahren, die sich uns dabei in den Weg gestellt haben, waren die Kreaturen, die dort heimisch sind, sowie Sand, Staub und Hitze.\n\nDie Allianz scheint nun aber Wind von unserem Unterfangen bekommen zu haben. Ein Rennen hat begonnen. Ein Rennen um die natürlichen Ressourcen und um deren Verteidigung.\n\nWir brauchen jede helfende Hand, die wir bekommen können. Ich hoffe, Ihr werdet uns unterstützen.", sourceObjective = "Findet Silithyst, bringt es zum Silithystextraktor und sprecht anschließend mit General Kirika beim Lager der Horde in der Nähe des Regalschwarmbaus.", progress = "Hütet Euch vor den Gefahren der Wüste, {name}. Die Allianz könnte hinter jeder Düne lauern und jeder Schritt könnte somit Euer letzter sein.", completion = "Ausgezeichnete Arbeit, {name}. Diese Ressourcen kommen sofort zum Rest der Vorräte. Jedes Bisschen trägt zu unserem Sieg und zur Schwächung unserer Feinde bei.", sourceObjectiveStatus = "unverified-source-field" }
quests[9423] = { id = 9423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Obadei", description = "Jetzt, da sich Sedais Tod bestätigt hat, liegt es an Euch, Obadei die traurige Nachricht zu überbringen.", sourceObjective = "Kehrt zu Anachoret Obadei beim Tempel von Telhamat auf der Höllenfeuerhalbinsel zurück und berichtet ihm von Sedais Tod.", completion = "Sedai, mein geliebter Bruder... \n\nDiese feigen Orcs! Er war unbewaffnet, wie konnten sie nur?\n\nLasst mich alleine, {name}. Ich danke Euch für Eure Hilfe, doch ich brauche jetzt etwas Zeit für mich selbst.", sourceObjectiveStatus = "unverified-source-field" }
quests[9424] = { id = 9424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Makurus Rache", description = "Sedai war für Makuru wie ein Bruder. Ich schulde ihm mein Leben und noch weit mehr! Sie sagen, Makuru sei verrückt, doch wenn die Omenai nach seinem Tod nichts tun wollen, dann sind sie die wahren Verrückten!\n\nMakuru kann in dieser Welt nicht viel sein Eigen nennen, aber ich werde Euch mit Freuden meinen einzigen Besitz überlassen, wenn Ihr Sedai rächt. \n\nIch habe die braunen Orcgrunzer schon mal gesehen, oben in den Bergen, im Nordosten. Sie hassen uns! Sie haben unser Mitleid nicht verdient! Geht und rächt Sedais Tod. Bringt mir ihre Ahnenperlen als Beweis!", sourceObjective = "Makuru im Tempel von Telhamat auf der Höllenfeuerhalbinsel möchte, dass Ihr ihm 10 Ahnenperlen der Mag'har bringt.", progress = "Habt Ihr Sedai in Makurus Namen gerächt?", completion = "Ja... Rache! Ihr wart gut.\n\nNehmt dies, es war ein Geschenk von Sedai. Wenn Makuru es behält, stimmt es ihn nur traurig.", sourceObjectiveStatus = "unverified-source-field" }
quests[9425] = { id = 9425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht an Tarrens Mühle", description = "Ah, gut Euch hier zu sehen, {class}! Ich habe eine Aufgabe, die wie für Euch gemacht ist.\n\nAls neue Mitglieder der Horde müssen wir dafür sorgen, dass wir sie bei ihren Unternehmungen unterstützen und bei ihren Problemen helfen. Dann werden sie uns auch bereitwilliger bei unseren helfen.\n\nReist zum Dorf der Verlassenen, Tarrens Mühle, im Vorgebirge des Hügellands im Südwesten. Meldet Euch bei Beraterin Morgenabend, wenn Ihr da seid.", sourceObjective = "Reist nach Tarrens Mühle im Vorgebirge des Hügellands und sprecht mit Beraterin Morgenabend.", completion = "Sieh an, sieh an! Noch einer meiner Brüder um einzuspringen. Gut! Unsere Freunde von den Verlassenen brauchen sehr viel Hilfe, {class}. Fragt herum, wo Ihr Euch nützlich machen könnt.\n\nIch weiß, dass Ihr sie nach bestem Wissen und Gewissen unterstützen werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[9426] = { id = 9426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Teiche von Aggonar", description = "Seit den Tagen, in denen wir dieses Land Draenor nannten, hat sich viel geändert. Teile des Landes wurden durch die Verderbtheit der Dämonen für immer verwandelt.\n\nDazu gehören die Teiche von Aggonar. Einst befanden sich an diesem Ort die heiligen Quellen unseres Volkes. Das Blut des Dämonen Aggonar hat die Essenz des geheiligten Wassers verschmutzt. Dieses teuflische Blut hat verderbte Kreaturen vorgebracht, die ausgelöscht werden müssen, wenn wir die Teiche jemals zurückfordern möchten. Reist von hier aus nach Osten und tötet die Teufelsblutelementare und den Schleim, der sich in den Teichen herumtreibt.", sourceObjective = "Amaan der Weise möchte, dass Ihr zu den Teichen von Aggonar geht und 6 Teufelsblutschrecken und 6 mörderische Faulschleime tötet.", completion = "Ja, ich fühle, wie die teuflische Präsenz in den Teichen abnimmt.\n\nIhr habt gute Arbeit geleistet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9427] = { id = 9427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinigung des Wassers", description = "Ich muss euch bitten, das, was wir angefangen haben, zu Ende zu bringen. Jetzt, da der teuflische Einfluss nachgelassen hat, müsst Ihr diese Reinigungsphiole nehmen und sie auf den Ursprung der Verderbnis schütten, Aggonars Leiche.\n\nIhr könnt die Knochen des Dämonen am nördlichen Ende der Teiche finden. Aber seid vorsichtig, seine Essenz ist immer noch nicht ganz aus dieser Welt verschwunden.", sourceObjective = "Amaan der Weise möchte, dass Ihr zu den Teichen von Aggonar reist und die Reinigungsphiole bei Aggonars Leiche benutzt. Kehrt zu ihm zurück, wenn Ihr das Wasser von Aggonars Essenz befreit habt.", progress = "Ich seid zurück, {name}. Ist das Wasser gereinigt?", completion = "Die Essenz von Aggonar lebte in seinem verderbten Nachkommen Aggonis weiter. Dank Eures Erfolgs gegen den Dämon können wir nun beginnen, die Teiche zu ihrer ursprünglichen Reinheit zurückzuführen.\n\nIhr habt unseren Dank, {name}. Eure Arbeit hat einen tiefen Eindruck in dieser Welt hinterlassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9428] = { id = 9428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht an den Splitterholzposten", description = "<Die Botschafterin senkt die Stimme und beugt sich zu Euch.>\n\nEuer Ruf eilt Euch voraus, {name}. Ich möchte, dass Ihr zum Splitterholzposten im Eschental reist. Zu Fuß gelangt man am einfachsten durch Durotar, das Brachland und dann an der Weggabelung nach Norden dorthin.\n\nWenn Ihr dort angekommen seid, sprecht mit Berater Sonnenschwur. Reist vorsichtig, das Eschental kann sehr gefährlich sein!", sourceObjective = "Reist zum Splitterholzposten im Eschental und sprecht mit Berater Sonnenschwur.", completion = "Die Botschafterin hat uns bereits informiert, wir haben Euch schon erwartet.\n\nSie möchte, dass Ihr hier so viel tut, wie Ihr nur könnt, um uns zu helfen. Sie sprach davon, unsere Freundschaft zum Rest der Horde zu festigen.\n\nFragt herum - weiter hinten im Posten gibt es Einige, die Eure Hilfe benötigen. Ich habe auch gehört, dass es einen weiteren Außenposten der Horde, den Außenposten von Zoram'gar, an der Küste ganz im Westen gibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9429] = { id = 9429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reist nach Dunkelhain", description = "Mir wurde gesagt, dass es einen Dorn in der Seite des Königreichs von Sturmwind gibt, Dämmerwald genannt. Dieser Ort ist erfüllt vom bösen und niederträchtigen Gestank des Untodes.\n\nDa wir versuchen, so gut wie möglich zu helfen, möchte ich, dass Ihr nach Südosten zu der größeren Menschensiedlung Dunkelhain reist. Anachoret Delan wird dort auf Eure Ankunft warten.", sourceObjective = "Reist nach Dunkelhain im Dämmerwald und sprecht mit Anachoret Delan.", completion = "Seid gegrüßt, {class}. Ich hoffe, Eure Reise hierher war angenehm.\n\nDie armen Seelen hier werden von allen Seiten von den Kreaturen der Nacht bedroht. Wir wünschen daher, dass Ihr ihnen so viel Hilfe wie möglich dabei zukommen lasst, die Dunkelheit zurückzudrängen.\n\nSeht Euch im Dorf um und lernt seine Einwohner kennen. Bitte, {name}, helft ihnen, wo immer Ihr könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9430] = { id = 9430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relikte von Sha'naar", description = "Wie ich es Euch bereits sagte, ich brauche mein Augenlicht nicht, um zu sehen, was andere nicht zu erkennen vermögen. Ich werde nicht verurteilen, was Ihr in Makurus Namen getan habt, dennoch denke ich, Ihr solltet über das, was Euch Eure Augen zeigen, hinausblicken.\n\nReist zu den Ruinen von Sha'naar im Südwesten und sammelt so viele Relikte ein, wie Ihr finden könnt. Wenn es das Schicksal so will, werdet Ihr finden, was wir brauchen.\n\nDie Bedeutung meiner Bitte mag Euch im Moment unklar sein, doch habt vertrauen, {name}. Der Geduldige wird erleuchtet werden.", sourceObjective = "Amaan der Weise beim Tempel von Telhamat auf der Höllenfeuerhalbinsel möchte, dass Ihr zu den Ruinen von Sha'naar reist und 10 Relikte von Sha'naar einsammelt.", progress = "Habt Ihr die Relikte aus Sha'naar bei Euch, {name}?", completion = "Das Glück hat Euch gesegnet. Genau wie ich es erhofft hatte, habt Ihr ein ganz besonderes Relikt zwischen all den anderen gefunden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9431] = { id = 9431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine andere Lösung", description = "Was hat es zu heißen, wenn ein Sin'dorei auf dem Gipfel einer vom Wind gepeitschten Plattform in Tausend Nadeln steht anstatt in den Hallen von Silbermond?\n\nGanz einfach. Meine Brüder wollen mich nicht mehr haben. Jede Abschrift meiner Abhandlung über die natürliche Heilung unserer Abhängigkeit wurde verbrannt.\n\nIch kann meine Forschungen hier sicher fortsetzen, aber ich habe keine Reagenzien. Wenn Ihr bereit wärt, etwas reinigende Erde von den donnernden Felskloppern am westlichen Ende der Nadeln zu besorgen und zu meinem Verbündeten beim Weißgipfelposten zu bringen, wäre ich Euch sehr dankbar.", sourceObjective = "Sammelt 2 Handvoll reinigende Erde von den donnernden Felskloppern und bringt sie zu Wizlo Lagerputzer beim Weißgipfelposten.", progress = "Magistrix Elosais Nachricht ist ein wenig rätselhaft, aber ich glaube, ich verstehe, was sie von mir will. Wenn Ihr die Erde habt, von der sie spricht, dann kann ich sie in das Gefäß füllen, das Ihr für das Wasser des Mondbrunnens braucht.", completion = "Was? Sie hat nichts von dem Mondbrunnen gesagt? Aber sie wusste doch die ganze Zeit, dass sie das Wasser brauchen würde? Ich weiß, das Ganze ist etwas verrückt, aber ich bin niemand, der einen Kunden wegscheucht, vor allem nicht, wenn es mein einziger ist.\n\nZugegeben, sich in eine Elfensiedlung einzuschleichen und das Wasser aus ihrem Mondbrunnen zu stehlen ist nicht unbedingt das Klügste, was ich je für einen Kunden getan habe, aber ihr Gold ist so gut wie jedes andere!", sourceObjectiveStatus = "unverified-source-field" }
quests[9432] = { id = 9432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reist nach Astranaar", description = "Ich bin froh, dass Ihr helfen wollt. Es gibt in der Tat etwas, was Ihr tun könnt.\n\nAls Teil unseres Bündnisses mit der Allianz möchte ich, dass Ihr zur Elfenstadt Astranaar reist. Sie befindet sich im Eschental, einem großen Wald südlich von Dunkelküste auf dem Kontinent Kalimdor.\n\nBitte sprecht mit Verteidigerin Palanaar, wenn Ihr angekommen seid, und fragt nach, ob es etwas gibt, bei dem Ihr den Bewohnern behilflich sein könnt.", sourceObjective = "Reist nach Astranaar im Eschental und sprecht mit Verteidigerin Palanaar.", completion = "Es ist immer schön, ein halbbekanntes Gesicht zu sehen. Ihr müsst {name} sein. Abgesandte Valustraa hat mir gesagt, dass ich Euch erwarten soll.\n\nDie Einwohner des Eschentals brauchen Eure Hilfe, {class}. Sprecht mit den Leuten in Astranaar und schaut, wo Ihr sie unterstützen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9433] = { id = 9433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Tauchgang im Mondbrunnen", description = "Schaut mich nicht so an! Ich habe nicht behauptet, dass ich Euch mit einer Kelle und einer Flasche zum Mondbrunnen von Thalanaar schicke!\n\nIch habe ein wenig an einem Produkt, das ich für einen Kunden transportiert habe, äh... herumexperimentiert. Ehrlich gesagt habe ich bereits eine tragbare Steuerungskonsole für den Robotron in der Nähe von Thalanaar aufgestellt. Ihr müsst diese Steuerungseinheit mitnehmen und in der Nähe meiner versteckten Konsole benutzen.\n\nWenn mein Kunde je erfährt, dass ich den Robotron auch nur aus der Verpackung genommen habe, hängt er mich an den Ohren auf!", sourceObjective = "Benutzt die Bedienungseinheit für Robotron in der Nähe der versteckten Steuerungskonsole in einer kleinen Gruppe von Büschen am Rand der Nadel, die sich am dichtesten an Thalanaar befindet, und übernehmt die Steuerung des Robotron 3000. Steuert den Roboter zum westlichen Ende von tausend Nadeln zum Allianzaußenposten von Thalanaar. Benutzt den Roboter, um eine Probe Mondbrunnenwasser zu besorgen und bringt sie zu Wizlo Lagerputzer beim Weißgipfelposten.", progress = "Habt Ihr die Aufgabe schon erfüllt?", completion = "Das lief besser, als ich erwartet habe! Ein weiterer Erfolg für den guten alten Erfindergeist der Goblins!\n\nDas einzige Problem ist, dass er voller Staub ist! Ich werde Ewigkeiten brauchen, um ihn zu reinigen und in seine Kiste zurück zu packen.\n\nAber Zeit ist das Einzige, von dem ich mehr als genug habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[9434] = { id = 9434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Tonikum testen", description = "<Wizlo nimmt dem Roboter die Wasserprobe ab und legt sie zusammen mit der Felskloppererde und verschiedenen anderen Dingen in eine Kiste.>\n\nSo, das ist alles auf Magistrix Elosais Liste. Sagt ihr, dass es mir eine Ehre war, mit ihr zusammen zu arbeiten, und dass ich ihr viel Glück bei ihren Forschungen wünsche.", sourceObjective = "Bringt die Kiste mit Reagenzien zu Magistrix Elosai im Freiwindposten.", progress = "Konnten Wizlo und Ihr die Reagenzien sammeln?", completion = "Ausgezeichnet, wie es aussieht, ist alles da. Jetzt muss ich nur noch alles zusammenmischen und es ausprobieren. Wenn das Tonikum die Wirkung hat, die es laut meinen Forschungen haben sollte, habe ich vielleicht einen Weg entdeckt, die Magiesucht meines Volkes zu lindern.\n\nIhr werdet gleich Zeuge eines historischen Augenblicks werden, {name}. Ohne Eure Hilfe wäre dies niemals möglich gewesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9435] = { id = 9435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermisste Kristalle", description = "Wenn man etwas mit Sicherheit über das Hügelland sagen kann, dann, dass es auserkoren wurde, um unter dem Schatten des Krieges zu leben. Sogar etwas so Harmloses wie eine Wagenladung Steine kann als Ziel dienen.\n\nNormalerweise ist der Verlust von Baumaterial kein allzu großes Problem, aber bei der letzten Lieferung aus dem Azurschacht war eine Kiste mit seltenen Kristallen dabei, die ich sehr gerne untersucht hätte. Plünderer der Verlassenen haben den Wagen abgefangen und ihn nach Nordosten zu einem Turm gebracht, den sie wiederaufbauen wollen. Wir müssen diese Kristalle zurückholen, {class}!", sourceObjective = "Besorgt die Lieferung seltener Kristalle von den Verlassenen und bringt sie zu Huraan in Süderstade zurück.", progress = "Konntet Ihr die Kristalle von den Verlassenen zurückholen?", completion = "Dem Licht sei Dank! Laut dem Brief des Vorarbeiters scheint diese Kiste mit Kristallen die einzigen bekannten Proben der Mine zu enthalten. Wenn wir sie verloren hätten, {name}, hätten wir vielleicht nie etwas Ähnliches zu Gesicht bekommen.\n\nIch kann Euch nicht genug für Eure Hilfe danken.", sourceObjectiveStatus = "unverified-source-field" }
quests[9436] = { id = 9436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erkenntnisse über die Blutskalpe", description = "Das trifft sich gut, {class}. Auf meinen Reisen habe ich die Kampftechniken der verschiedenen Trollstämme untersucht und eine Entwicklung erkannt. Die Blutskalpe in den Ruinen von Tkashi und Bal'lal im Norden benutzen die gleichen Taktiken wie die Amani in den nördlichen Wäldern.\n\nIhre Magie scheint sich in eine interessante Richtung entwickelt zu haben, und sie haben sie benutzt, um der mächtigste Stamm in der Gegend zu werden. Sie könnte der Kern einer Waffe gegen die Amani sein, aber ich muss noch mehr darüber herausfinden.", sourceObjective = "Nemeth Falkenauge im Basislager von Grom'gol möchte, dass Ihr ihm ein Totem der Blutskalpe von einem Schamanen der Blutskalpe bringt.", progress = "Enttäuscht mich nicht, {name}. Wenn wir die Magie der Blutskalpe für unsere Zwecke einsetzen können, kann mein Volk vielleicht die Amanibedrohung auslöschen.", completion = "Gut gemacht. Nun, das ist interessant...\n\nDie Sprache auf dem Totem wird ein Troll niemals erlernen können, aber uns ist sie wohlbekannt. Sie macht den Träger des Totems zu einem Verbündeten eines Wasserelementar namens Naias und erkennt ihn als würdig an, seine Macht zu verwenden.\n\nDas kommt sehr unerwartet, aber es ist nicht verheerend, {name}. Mit Eurer Hilfe möchte ich der Sache noch weiter auf den Grund gehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9437] = { id = 9437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Untergang der Morgenbö", description = "Die Oger hier sind für nichts außer dreckige Witze, bitteres Bier und Wettkämpfe im Köpfe-aneinander-Schlagen zu gebrauchen. Als mein Schiff, die Morgenbö, untergegangen ist, haben sich diese Hunde von Theramore mit meiner Ladung und dem letzten überlebenden Crewmitglied aus dem Staub gemacht. Ich habe mich auf der Suche nach Hilfe hierher begeben, aber diese nichtsnutzigen Oger haben mich nur dumm angeschaut, als ich ihnen erzählt habe, was passiert ist.\n\nIch könnte die Hilfe eines zuverlässigen Helden brauchen, um die Überreste meiner Ladung und Ithania aus der Nordwacht zu retten. Der Turm befindet sich im Nordosten.", sourceObjective = "Balandar Sternenlicht in Brackenwall möchte, dass Ihr die Fracht der Morgenbö wiederholt und den Ersten Maat Ithania von den Streitkräften von Theramore in der Nordwacht befreit.", progress = "Habt Ihr Ithania befreit und meine Fracht von diesen glorifizierten Freibeutern zurückgeholt?", completion = "Gut gemacht, {name}! Sobald Ithania Zeit hatte, sich auszuruhen, und meine Vorbereitungen abgeschlossen sind, werden wir aus diesem sumpfigen Ödland hier wieder in die Zivilisation aufbrechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9438] = { id = 9438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bote für Thrall", description = "Seitdem wir das erste Mal die Scherbenwelt betreten haben, hat der Kriegshäuptling auf diese Nachricht gehofft. Nun seid Ihr es, der die Ehre hat, ihm persönlich die Botschaft der Mag'har zu übermitteln.\n\nVerliert keine Zeit, {name}. Nehmt diesen Brief, er enthält mein persönliches Siegel. Es gibt nichts, was Thrall mehr erfreuen wird, als die Botschaft, die Ihr bei Euch tragt.", sourceObjective = "Reist nach Orgrimmar und übergebt ThrallNazgrels Brief.", progress = "Ihr bringt Kunde aus der Scherbenwelt, {class}? Sodann, sprecht!", completion = "<Thralls Augen werden immer größer, als er Nazgrels Brief liest.>\n\nMein Volk... wir müssen sie erreichen. Wir müssen Nagrand so schnell wie möglich erreichen!", sourceObjectiveStatus = "unverified-source-field" }
quests[9439] = { id = 9439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unabgeholtes Gepäck", description = "Das ist Kargath? Oh je. Ich habe eine... nun, eine Art Siedlung erwartet, ein Zeichen von Zivilisation inmitten der Wildnis.\n\nDas muss ein Fehler sein, diese Hütte voller ungehobelter, ungewaschener, dümmlich grinsender Wilder kann nicht das Hauptquartier des Expeditionskorps sein. Diese flegelhaften Barbaren haben es gewagt, mich auszulachen, als ich ihnen erzählt habe, wie die Dunkeleisenzwerge mich überfallen haben und dann in der Festung Angor verschwunden sind. Ich kann darauf zählen, dass Ihr mir meinen Besitz und meine Würde zurückbringt, oder?", sourceObjective = "Holt den Beutel des Beraters und das Rapier des Beraters aus der Festung Angor und kehrt dann zu Berater Sarophas in Kargath zurück.", progress = "Um Sonnenwanderers Willen, starrt mich nicht so an! Es ist schon schwer genug für mich, dass ich hier in meiner verschmutzten Kleidung ausharren muss! Nach allem, was ich durchgemacht habe, ist das Letzte, was ich brauchen kann, angestarrt zu werden. Habt Ihr meinen Besitz aus diesem Loch in der Erde, dass die Dunkeleisenzwerge eine Festung nennen, geholt?", completion = "Ihr bewirkt Wunder, {name}! Ich kann Euch sagen, dass ich noch nie in meinem Leben so begierig darauf war, mich umzuziehen.\n\nUnd mein Rapier! Ich habe mich ohne meine Klinge richtig nackt gefühlt.\n\nIhr müsst für Eure Mühen belobigt und belohnt werden! Keiner kann behaupten, dass Sarophas die kleinen Leute, die ihm auf seinem Weg geholfen haben, je vergessen hätte!", sourceObjectiveStatus = "unverified-source-field" }
quests[9440] = { id = 9440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleine Häppchen", description = "Ich baue gerade eine Waffe gegen die Draenei und Ihr werdet mir dabei helfen!\n\nDie Verirrten sind die zurückgebliebenen Vettern der Draenei und ich habe ein paar Experimente mit ihnen durchgeführt. Ihr müsst nur ein paar teuflische Häppchen zu ihrem Vieh bringen. Wenn sie die Tiere dann schlachten und essen werden sie verflucht sein! Das wird es dem spießigen Anachoreten Avuun im sicheren Hafen zeigen!\n\nGeht nun und beeilt Euch! Ihr findet die Verirrten und ihre eingesperrten Tiere im Nordosten in der Zuflucht der Verirrten.", sourceObjective = "Verfüttert die teuflischen Häppchen an die gefangenen Tiere der Verirrten. Bringt die Überbleibsel zu Cersei Abendsänger in Steinard in den Sümpfen des Elends.", progress = "Habt Ihr den gefangenen Tieren alle Häppchen gefüttert? Wartet! Ihr habt doch diesem dummen Menschen, den sie im Käfig halten keines gegeben, oder?\n\nOh, gut! Das wäre nur Verschwendung gewesen!", completion = "Oh, ausgezeichnet! Ich kann es kaum erwarten, die Ergebnisse dieser letzten Fuhre zu sehen!\n\nNun, Ihr habt fabelhafte Arbeit geleistet, Liebchen. Ich wünschte, ich könnte Euch für die Unterhaltung, die Ihr mir bereitet habt, mehr geben, aber Ihr wisst ja, wie es ist. Hier in den Sümpfen kann man nicht viel Geld machen.\n\nIch bin mir sicher, es war Euch den Spaß trotzdem wert!", sourceObjectiveStatus = "unverified-source-field" }
quests[9441] = { id = 9441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entsandt zu den Mag'har", description = "Nachdem Ihr mir diese Botschaft überbracht habt, würde ich umgehend in die Scherbenwelt aufbrechen. Leider machen wichtige Angelegenheit meine Anwesenheit in Durotar erforderlich.\n\nIch werde den Mag'har umgehend einen würdigen Tribut als Zeichen unserer Freundschaft zukommen lassen. Des Weiteren entsende ich meine fähigsten Diplomaten. All das wird Vorbereitungen und Zeit kosten... wir benötigen jemanden, der uns schon heute vor den Mag'har würdig vertreten kann.\n\nIch setzte mein gesamtes Vertrauen in Euch, {name}. Reist zum Posten der Mag'har auf der Höllenfeuerhalbinsel und bietet ihnen Eure Dienste im Namen unseres gesamten Volkes an. Enttäuscht mich nicht, {name}. Zuviel hängt davon ab.", sourceObjective = "Kehrt zu Gorkan Blutfaust beim Posten der Mag'har auf der Höllenfeuerhalbinsel zurück und bietet ihm im Namen Thralls Eure Dienste an.", completion = "Es bedeutet uns sehr viel, dass Ihr uns in diesen schwierigen Zeiten Eure helfende Hand reicht. Niemals werden wir Euch, noch denjenigen vergessen, der Euch hierher entsandt hat.\n\nEuch gebührt unser Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[9442] = { id = 9442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine erschöpfende Krankheit", description = "Es ist schön, dass Ihr uns helfen wollt, {name}. Unsere Grunzer haben verdorbenes Wasser getrunken und sind krank geworden. Leider fehlt mir eine Zutat für eine Heilsalbe. Ich benötige einen seltenen Pilz namens Trockenkappe.\n\nUnser wichtigster Befehl ist, unseren Aufenthaltsort geheim zu halten, weswegen ich nicht riskieren kann, bei der Suche danach entdeckt zu werden. Der einzige Ort, an dem man auf der Höllenfeuerhalbinsel Trockenkappen finden kann, ist eine Höhle in der Nähe der großen Kluft, südlich von hier.\n\nSeid äußerst vorsichtig, wenn Ihr Euch entschließen solltet, danach zu suchen.", sourceObjective = "Erdruferin Ryga beim Posten der Mag'har auf der Höllenfeuerhalbinsel möchte, dass Ihr 1 Trockenkappe aus einer Höhle in der großen Kluft besorgt.", progress = "Habt Ihr den Pilz schon besorgt, {name}?", completion = "Grokan hat viel Gutes über Euch gesagt. Wie sich herausstellt, war alles wahr.\n\nVielen Dank für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[9443] = { id = 9443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das sogenannte Mal des Lichtbringers", description = "Einst war ich ein Schüler von Uther Lichtbringer, dem Gründervater der Ritter der Silberhand. Ich sah sein Versagen bei der Ausbildung von Prinz Arthas. Es führte zu der Zerstörung meines Heimatlandes, Quel'Thalas, und ich gebe Uther die alleinige Schuld daran! Und nun ruht er in einem Grabmal, das zu seinen Ehren erbaut wurde - wie liebenswert.\n\nMeine Quellen berichteten mir, dass diese Scharlachroten Narren eines seiner 'heiligen' Relikte in der Spitze ihres Wachturms, nahe den Toren Herdweilers aufbewahren.\n\nBegebt Euch in die westlichen Pestländer und bringt es mir.", sourceObjective = "Nehmt das Mal des Lichtbringers an Euch und kehrt anschließend zu Mehlar Dämmerklinge beim Bollwerk in den westlichen Pestländern zurück.", progress = "Wenn Ihr das Mal an Euch gebracht habt, werden wir es ein wenig verändern; es verbessern.", completion = "Der erste Schritt ist vollbracht. Gebt mir das Mal des Lichtbringers und ich werde es in etwas Passenderes verwandeln.\n\nDann wird die Rache endlich mein sein, {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[9444] = { id = 9444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entweiht Uthers Grabmal", description = "So, dass ist viel besser. Ich habe ihm etwas dämonische Magie hinzugefügt.\n\nNun müsst Ihr es zu seiner Ruhestätte in den westlichen Pestländern bringen. Benutzt das verderbte heilige Symbol in der Gegenwart von Uthers Statue, um sein Grabmal zu entweihen! Geht nahe heran, sonst kann die Magie ihre Wirkung nicht entfalten.\n\nDas Grabmal befindet sich südöstlich von den Ruinen Andorhals. Kehrt zu mir zurück, wenn Euer Werk vollbracht ist.\n\nBeeilt Euch, {class}!", sourceObjective = "Entweiht Uthers Grabmal und kehrt anschließend zu Mehlar Dämmerklinge beim Bollwerk in den westlichen Pestländern zurück.", progress = "Ist es vollbracht? Uthers Grabmal, wurde es entweiht?", completion = "Er vergibt mir? Er VERGIBT MIR?!!!\n\nIch schere mich nicht um das Geschwätz des alten Geistes - es war allein seine Schuld! Alles, was Quel'Thalas erdulden musste, war das Resultat seiner Inkompetenz!\n\nEs ist wohl offensichtlich, dass der Akt der Entweihung fehlschlug. Geht mir aus den Augen! Ich muss alles nochmal überdenken.", sourceObjectiveStatus = "unverified-source-field" }
quests[9446] = { id = 9446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Grab des Lichtbringers", description = "Jetzt, da Ihr das Mal des Lichtbringers zurückgeholt habt, müssen wir es nur noch zu Uthers Grabmal bringen.\n\nWollt Ihr mich dorthin begleiten? Es ist nicht weit und ich würde Eure Gesellschaft genießen. Danach könnt Ihr hierher zurückkehren und der Hohepriesterin MacDonnell von Eurer Erfahrung berichten.\n\nWas haltet Ihr davon, {name}?", sourceObjective = "Begleitet Anachoret Truuen zu Uthers Grabmal in den westlichen Pestländern. Sprecht danach mit Hohepriesterin MacDonnell im Zugwindlager in den westlichen Pestländern.", completion = "Der Lichtbringer ist Euch erschienen? Das ist erstaunlich! Und das alles habt Ihr durch Eure selbstlose Hilfe für den Anachoreten erreicht!\n\nWenn nur die Hälfte der Geschichten wahr ist, war Uther ein großartiger Mann. Und genau wie er seid auch Ihr ein wahrer Held für alle guten Leute in Azeroth, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[9447] = { id = 9447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salbe verabreichen", description = "Ich habe mit den Kräutern, die Ihr mir gebracht habt, eine Salbe zubereitet, die die Stärke der Grunzer wiederherstellen sollte. Nehmt sie und verabreicht sie allen entkräfteten Grunzern an, die Ihr hier in der Nähe seht.", sourceObjective = "Erdruferin Ryga möchte, dass Ihr die Heilsalbe 10 entkräfteten Grunzern beim Posten der Mag'har auf der Höllenfeuerhalbinsel verabreicht.", progress = "Ihr seid zurück, {name}. Habt Ihr Eure Aufgabe erledigt?", completion = "Mögen die Geister Euch segnen, {name}. die Mag'har stehen in Eurer Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[9448] = { id = 9448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mitleid mit den Verfluchten", description = "Diese Blutelfenhexe, Cersei Abendsänger, hat die Verirrten verflucht! Ich weiß es einfach! Ich weiß nicht wie und warum, aber die Folgen sind verheerend. Viele der Verirrten wurden noch weiter verderbt und mit noch teuflischeren Energien verflucht!\n\n{class}, könnt Ihr tief in Eurem Inneren etwas Mitleid für diese armen Kreaturen aufbringen? Sie sollten ihr Leben nicht in einem so furchtbaren Zustand verbringen.\n\nIhr findet die verfluchten Verirrten in der Zuflucht der Verirrten, den Pfad hinunter nach Osten.", sourceObjective = "Tötet 3 Verfluchte der Verirrten und kehrt dann zu Anachoret Avuun im sicheren Hafen in den Sümpfen des Elends zurück.", completion = "Es ist also getan. Ich danke Euch, dass Ihr ein Herz gezeigt habt. Nachdem Cersei ihnen verderbtes Essen gegeben hat, gab es keinen anderen Weg.\n\nNun ruhen sie in Frieden. Hoffentlich zeigen meine Studien an den anderen Früchte, damit sie gerettet werden können.", sourceObjectiveStatus = "unverified-source-field" }
quests[9449] = { id = 9449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Erde", description = "Die Zeit ist gekommen, {name}. Euer Körper und Euer Geist sind an einem Punkt angelangt, an dem Ihr direkt mit den elementaren Geistern Azeroths kommunizieren müsst.\n\nLasst Euch jedoch gewarnt sein. Ich spüre, dass unser ungewöhnliches Betreten dieser Welt und dessen unglückliche Nebenwirkungen die Erdgeister erzürnt und zu einem Ungleichgewicht der Elemente geführt haben.\n\nWollt Ihr Euer Erdtotem erschaffen, so müsst Ihr zuerst mit dem Geist des Tals sprechen. Ihr findet ihn im heiligen Hain, der sich an die Hügel im Nordwesten schmiegt.", sourceObjective = "Sprecht mit dem Geist des Tals beim heiligen Hain im Am'mental.", completion = "Es ist sehr kühn von Euch, meinen Rat zu ersuchen, nach all dem, was Eure Leute diesen Inseln angetan haben, Fremder! Dennoch, Euer Mut spricht für sich, also werde ich Teile meines Wissens preisgeben.\n\nDie Erde unter Euren Füßen ist die Grundlage aller Dinge. Der Himmel, das Wasser, sogar große Feuer - alle lasten auf ihren Schultern. Während die anderen oft in wilden Stürmen toben, hält die Erde geduldig aus. Sie verleiht Eurem Innern Stärke und Kraft.\n\nJetzt werdet Ihr Euch beweisen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9450] = { id = 9450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Erde", description = "Das Gleichgewicht der Elemente wurde durch das gewaltsame Eindringen der Draenei ins Tal gestört. Euer Absturz hat die Erdgeister erzürnt und gegen die anderen Elemente gewendet. Ihr werdet sehen, dass man die Elemente nur dann verstehen kann, wenn diese in Einklang sind.\n\nFolglich müsst Ihr das Gleichgewicht wieder herstellen. Im Hain hinter mir findet Ihr ruhelose Erdgeister, die gegen die anderen drei Elemente aufbegehren. Helft uns, stellt den Einklang wieder her.", sourceObjective = "Tötet 4 ruhelose Erdgeister und kehrt zum Geist des Tals beim heiligen Hain im Am'mental zurück.", progress = "Das Gleichgewicht der Elemente scheint noch immer gestört, {name}.", completion = "Ihr habt Euch gut geschlagen, {class}. Indem Ihr die Zahl der ruhelosen Geister reduziert habt, habt Ihr geholfen, das Gleichgewicht der Elemente wiederherzustellen, das Eure Leute unbeabsichtigterweise zerstört hatten.\n\nDas Gleichgewicht muss immer gewahrt bleiben. Auf Eurem Lebensweg als {class}, dürft Ihr diese Lehre nie vergessen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9451] = { id = 9451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Erde", description = "Ich werde Euch jetzt einen Teil meines physischen Wesens geben, damit Ihr Euer Erdtotem erschaffen könnt. Bringt es zu dem, der Euch hierher gesandt hat. Ihr und ich werden von nun an auf Lebzeiten miteinander verbunden sein.\n\nDie Kräfte der Erde werden Euch in Eurem Leben fortwährend zur Verfügung stehen. Wenn Eure Knochen am Ende Eurer Tage wieder zu uns zurückkehren, schließt sich der Kreislauf wieder.\n\nSetzt Eure Macht weise ein.", sourceObjective = "Bringt den Erdkristall zu Firmanvaar bei der Absturzstelle im Am'mental.", progress = "Zusammen werden die Zerschlagenen und die {race} ein tieferes Verständnis für die Mysterien der Elemente wiedererlangen.\n\nSeid Ihr mit der für die Herstellung Eures Erdtotems notwendigen Komponente zurückgekehrt?", completion = "Ausgezeichnet, {name}. Indem Ihr das Gleichgewicht der Elemente im Hain wieder hergestellt habt, habt Ihr auch für einen Einklang zwischen den Erdelementen dieser Welt und den {race} gesorgt. Möglicherweise zeigen diejenigen unter uns, die unseren Weg ablehnen, nun mehr Verständnis?\n\nIch werde ein Totem für Euch erschaffen, das mit den Elementen der Erde verbunden ist. Mit dessen Hilfe werdet Ihr die Kräfte der Erde auf Euren Wunsch herbeirufen können. Mit mehr Weisheit, werden sich Euch auch noch mehr Geheimnisse der Erde erschließen.\n\nHier, nehmt Euer Totem, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9452] = { id = 9452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnapper - sehr, sehr lecker!", description = "Ich habe festgestellt, dass es in diesen Gewässern von Schnappern nur so wimmelt. Das ist ein sehr, sehr leckerer Fisch.\n\nMit einem Fischernetz kann ich genug fangen, um dutzende von Draenei satt zu bekommen! Unglücklicherweise wurde ich erst kürzlich von einer Kreatur angegriffen, die man Murloc nennt, als ich im Fluss fischte. Ich wurde dabei verletzt und kann deshalb meine Arbeit nicht mehr verrichten. Ich brauche Hilfe!\n\nIhr müsst dieses Fischernetz lediglich in der Nähe von Schnapperschwärmen, die man im Kristalfluss östlich von hier findet, auswerfen.\n\nWas sagt Ihr? Vergesst aber nicht, das Netz nach getaner Arbeit wieder zurückzubringen.", sourceObjective = "Verwendet das Fischernetz der Draenei, um 10 Schnapper zu fangen. Bringt die Fische und das Netz anschließend zu Diktynna auf der Azurmythosinsel zurück.", progress = "Nehmt Euch vor den Murlocs in Acht: seltsame und extrem lästige kleine Kreaturen.", completion = "Ich hoffe Ihr hattet nicht zu viel Scherereien wegen der Murlocs, {name}. Ich bin Euch sehr dankbar für alles, was Ihr getan habt.\n\nSoll ich Euch vielleicht das Angeln beibringen? Ich kann Euch sogar eine Angelrute und ein glänzendes Schmuckstück geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[9453] = { id = 9453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet Acteon!", description = "Ihr habt das wunderbar gemacht, {name}. Unsere Leute werden Euch für diesen Fang sehr dankbar sein. Ach ja, könntet Ihr diese Ladung Schnapper vielleicht zu Acteon bei der Azurwacht bringen?\n\nEr dürfte leicht zu finden sein, da er diese Lieferung bereits erwartet.", sourceObjective = "Bringt die Ladung Schnapper zu Acteon bei der Azurwacht.", progress = "Was haltet Ihr von meiner Rüstung? Habe sie selbst hergestellt! Sie unterscheidet sich zwar etwas von den traditionellen Rüstungen, die wir normalerweise tragen, ist aber sehr bequem.", completion = "Arme Diktynna... der Murloc hat ihr wohl einen ziemlichen Schrecken eingejagt.\n\n<Acteon seufzt.>\n\nHoffentlich heilen ihre Verletzungen bald...\n\nIhr haltet also nach Arbeit Ausschau, nun, davon gibt es bei der Azurwacht jede Menge!", sourceObjectiveStatus = "unverified-source-field" }
quests[9454] = { id = 9454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die große Mondweidenjagd", description = "Ihr macht Euch hier einen Namen, {name}. Warum versucht Ihr Euch nicht mal im Jagen?\n\nAuf Draenor würden unsere besten Jäger Tiere jagen, die den Mondweidenhirschen dieser Gegend sehr ähneln und den Namen Talbuk tragen.\n\nWenn Ihr denkt, Ihr seid 'Draenei' genug, dann zieht durch die Wildnis rund um die Azurwacht und tötet ausreichend Mondweidenhirsche und -böcke, um Eure Taschen mit ihrem Fleisch zu füllen.\n\nDie Hirsche grasen südlich der Azurwacht, die Böcke im Norden. Gebt auf ihre Hörner Acht!", sourceObjective = "Acteon bei der Azurwacht möchte, dass Ihr ihm 6 Mondweidenhirschlenden bringt.", progress = "Die Bälge der Hirsche taugen nichts, dafür ist ihr Fleisch köstlich zart.", completion = "Gut gemacht, {name}, gut gemacht!\n\nHier, während Ihr fort wart, habe ich ein paar der Lenden, die Ihr mir gebracht habt, zubereitet. Vielleicht wollt Ihr ja auch das Rezept haben?", sourceObjectiveStatus = "unverified-source-field" }
quests[9455] = { id = 9455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seltsame Funde", description = "Der Kristall, den Ihr beim Körper des Nachtpirscherjungen gefunden habt, scheint ein Teil der Exodar zu sein. Vielleicht ist dies eine Erklärung für das ungewöhnliche Aufkommen und Verhalten einiger Tiere dieser Gegend.\n\nBringt den Kristall zurück zur Azurwacht. Der Exarch wird sicherlich von dieser Entdeckung erfahren wollen.", sourceObjective = "Bringt den schwach leuchtenden Kristall zu Exarch Menelaous bei der Azurwacht.", progress = "Was habt Ihr gefunden? Wo?", completion = "Wie konnte solch ein Ding nur im Magen eines Nachtpirschers enden? Könnten die Trümmer des Absturzes noch mehr Kreaturen verseucht haben?", sourceObjectiveStatus = "unverified-source-field" }
quests[9456] = { id = 9456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachtpirscherjagd", description = "Ich werde nicht versuchen, irgendwelche Ausreden für das, was Ihr gefunden habt, zu finden. Es ist ganz klar unsere Schuld. Uns wurde von zertrümmerten Kristallfragmenten im östlich gelegenen Fluss berichtet, aber wir hatten beschlossen, diese Implikationen zu ignorieren. Wir können jetzt entweder auf dieser Insel herumsitzen und diese Tragödie beweinen, oder etwas tun, um eine Ausbreitung zu vermeiden.\n\nWenn Ihr es ertragen könnt, möchte ich, dass Ihr zurück in die Wildnis geht und so viele der infizierten Nachtpirscherjungen tötet, wie Ihr finden könnt.", sourceObjective = "Exarch Menelaous bei der Azurwacht möchte, dass Ihr 8 infizierte Nachtpirscherjungen tötet.", completion = "Ich hoffe nur, dass es nicht schon zu spät ist...", sourceObjectiveStatus = "unverified-source-field" }
quests[9457] = { id = 9457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ungewöhnlicher Patron", description = "Naias ist also das Genie hinter den Blutskalpen und ihrer fremdartigen Magie? Ich muss zugeben, dass ich nie gedacht hätte, dass meine Nachforschungen dort enden würden, aber unsere Erkenntnisse könnten sich vielleicht trotzdem als hilfreich herausstellen.\n\nVor der Küste im Nordwesten befindet sich eine kleine Insel, die von geringen Wasserelementaren bewohnt wird. Es gibt dort eine grobe Steinplatte, die den Trollen vielleicht als Altar dienen könnte. Bringt das Totem, das Ihr gefunden habt, zu diesem Altar. Vielleicht können wir diesen Naias ja hervorlocken und seine Macht in eine angenehmere Form bringen.", sourceObjective = "Benutzt Naias' Gabe in der Nähe des Altars von Naias, um den Wasserelementar Naias zu rufen. Besiegt ihn und kehrt dann zu Nemeth Falkenauge im Basislager von Grom'gol mit dem Herz von Naias zurück.", progress = "Was gibt es Neues von Naias, {name}?", completion = "Ich kann die rohe Macht in diesem Edelstein fühlen, {name}. Ich werde ihn nach Silbermond schicken, damit unsere Magister ihn weiter untersuchen können, aber ich bin mir sicher, dass er uns im weiteren Kampf gegen die Amani dienlich sein kann.\n\nEure Hilfe bei der Besorgung dieses Steins war unbezahlbar. Ich werde dafür sorgen, dass die Weltenwanderer den Namen des Helden, der diesen Fund möglich gemacht hat, erfahren.", sourceObjectiveStatus = "unverified-source-field" }
